const INDEX_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Invest Quest</title>\n  <style>\n    :root {\n      --paper: #fbfaf6;\n      --ink: #17211b;\n      --muted: #5e6b63;\n      --line: #d9ddd4;\n      --green: #168a58;\n      --green-soft: #dff4e7;\n      --red: #bc3d35;\n      --red-soft: #f8dfdc;\n      --gold: #c98918;\n      --gold-soft: #fff0c9;\n      --teal: #117c86;\n      --panel: #ffffff;\n      --shadow: 0 18px 50px rgba(23, 33, 27, .10);\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      min-height: 100vh;\n      color: var(--ink);\n      background:\n        radial-gradient(circle at top left, rgba(22, 138, 88, .12), transparent 28rem),\n        linear-gradient(140deg, #fbfaf6 0%, #eef7f4 48%, #fff6db 100%);\n    }\n\n    button,\n    input {\n      font: inherit;\n    }\n\n    button {\n      border: 0;\n      cursor: pointer;\n    }\n\n    button:disabled {\n      cursor: not-allowed;\n      opacity: .52;\n    }\n\n    .app {\n      width: min(1180px, calc(100% - 32px));\n      margin: 0 auto;\n      padding: 24px 0 36px;\n    }\n\n    .topbar {\n      min-height: 68px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-width: 0;\n    }\n\n    .logo {\n      width: 44px;\n      height: 44px;\n      border-radius: 8px;\n      background: linear-gradient(135deg, var(--green), var(--teal));\n      color: #fff;\n      display: grid;\n      place-items: center;\n      font-weight: 900;\n      box-shadow: var(--shadow);\n    }\n\n    h1,\n    h2,\n    h3,\n    p {\n      margin: 0;\n    }\n\n    h1 {\n      font-size: 28px;\n      line-height: 1.1;\n      letter-spacing: 0;\n    }\n\n    h2 {\n      font-size: 24px;\n      line-height: 1.15;\n      letter-spacing: 0;\n    }\n\n    h3 {\n      font-size: 16px;\n      line-height: 1.25;\n      letter-spacing: 0;\n    }\n\n    .muted {\n      color: var(--muted);\n    }\n\n    .pillrow {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      align-items: center;\n      justify-content: flex-end;\n    }\n\n    .pill {\n      min-height: 34px;\n      border: 1px solid var(--line);\n      background: rgba(255, 255, 255, .78);\n      border-radius: 999px;\n      padding: 7px 12px;\n      display: inline-flex;\n      align-items: center;\n      gap: 7px;\n      font-weight: 800;\n      white-space: nowrap;\n    }\n\n    .shell {\n      display: grid;\n      grid-template-columns: 320px minmax(0, 1fr);\n      gap: 18px;\n      align-items: start;\n    }\n\n    #dashboard.lesson-focus .shell {\n      grid-template-columns: 76px minmax(0, 1fr);\n      gap: 12px;\n    }\n\n    #dashboard.lesson-focus .side {\n      display: block;\n      padding: 8px;\n    }\n\n    #dashboard.lesson-focus .side .hero-art,\n    #dashboard.lesson-focus .side .legend {\n      display: none;\n    }\n\n    #dashboard.lesson-focus .side .tabbar {\n      margin: 0;\n    }\n\n    #dashboard.lesson-focus .side .tab {\n      min-height: 54px;\n      padding: 8px;\n      justify-content: center;\n    }\n\n    #dashboard.lesson-focus .side .tab-label {\n      display: none;\n    }\n\n    #dashboard.lesson-focus .side .tab-icon {\n      font-size: 22px;\n    }\n\n    .side,\n    .mainpanel,\n    .onboarding,\n    .card,\n    .modal {\n      background: rgba(255, 255, 255, .88);\n      border: 1px solid rgba(217, 221, 212, .9);\n      box-shadow: var(--shadow);\n      border-radius: 8px;\n    }\n\n    .side {\n      padding: 18px;\n      position: sticky;\n      top: 16px;\n    }\n\n    .mainpanel {\n      padding: 18px;\n      min-width: 0;\n    }\n\n    .hero-art {\n      height: 180px;\n      border-radius: 8px;\n      overflow: hidden;\n      margin: 0 0 16px;\n      border: 1px solid var(--line);\n      background: linear-gradient(160deg, #0f5f56, #f0b640);\n      position: relative;\n    }\n\n    .hero-art::before {\n      content: \"\";\n      position: absolute;\n      inset: 0;\n      background-image:\n        linear-gradient(140deg, rgba(255,255,255,.18) 0 1px, transparent 1px 100%),\n        linear-gradient(90deg, rgba(255,255,255,.12) 0 1px, transparent 1px 100%);\n      background-size: 28px 28px, 40px 40px;\n    }\n\n    .bars {\n      position: absolute;\n      left: 24px;\n      right: 24px;\n      bottom: 24px;\n      height: 100px;\n      display: grid;\n      grid-template-columns: repeat(7, 1fr);\n      align-items: end;\n      gap: 9px;\n    }\n\n    .bars span {\n      border-radius: 6px 6px 0 0;\n      background: rgba(255,255,255,.85);\n      min-height: 18px;\n    }\n\n    .bars span:nth-child(1) { height: 35%; }\n    .bars span:nth-child(2) { height: 55%; }\n    .bars span:nth-child(3) { height: 42%; }\n    .bars span:nth-child(4) { height: 76%; }\n    .bars span:nth-child(5) { height: 61%; }\n    .bars span:nth-child(6) { height: 88%; }\n    .bars span:nth-child(7) { height: 70%; }\n\n    .tabbar {\n      display: grid;\n      gap: 8px;\n      margin: 18px 0;\n    }\n\n    .tab {\n      width: 100%;\n      min-height: 44px;\n      display: flex;\n      align-items: center;\n      justify-content: flex-start;\n      gap: 10px;\n      padding: 10px 12px;\n      border-radius: 8px;\n      color: var(--ink);\n      background: transparent;\n      border: 1px solid transparent;\n      font-weight: 850;\n    }\n\n    .tab.active {\n      background: #fff;\n      border-color: var(--line);\n      box-shadow: 0 10px 24px rgba(23,33,27,.08);\n    }\n\n    .legend {\n      display: grid;\n      gap: 9px;\n      margin-top: 16px;\n      padding-top: 16px;\n      border-top: 1px solid var(--line);\n    }\n\n    .legend-item {\n      display: grid;\n      grid-template-columns: 44px 1fr;\n      align-items: center;\n      gap: 10px;\n      color: var(--muted);\n      font-size: 13px;\n      font-weight: 750;\n    }\n\n    .stripe {\n      height: 5px;\n      border-radius: 999px;\n    }\n\n    .stripe.red { background: var(--red); }\n    .stripe.green { background: var(--green); }\n    .onboarding-wrap {\n      min-height: calc(100vh - 48px);\n      display: grid;\n      place-items: center;\n    }\n\n    .onboarding {\n      width: min(760px, 100%);\n      overflow: hidden;\n    }\n\n    .onboarding-grid {\n      display: grid;\n      grid-template-columns: 285px minmax(0, 1fr);\n    }\n\n    .onboard-art {\n      min-height: 510px;\n      padding: 22px;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      background:\n        linear-gradient(160deg, rgba(17,124,134,.96), rgba(22,138,88,.90)),\n        repeating-linear-gradient(0deg, rgba(255,255,255,.18) 0 1px, transparent 1px 32px);\n      color: #fff;\n    }\n\n    .mini-chart {\n      height: 178px;\n      display: grid;\n      grid-template-columns: repeat(5, 1fr);\n      align-items: end;\n      gap: 10px;\n      margin-top: 22px;\n    }\n\n    .mini-chart span {\n      border-radius: 8px 8px 0 0;\n      background: rgba(255,255,255,.78);\n    }\n\n    .mini-chart span:nth-child(1) { height: 48%; }\n    .mini-chart span:nth-child(2) { height: 66%; }\n    .mini-chart span:nth-child(3) { height: 39%; }\n    .mini-chart span:nth-child(4) { height: 84%; }\n    .mini-chart span:nth-child(5) { height: 58%; }\n\n    .onboard-content {\n      padding: 26px;\n      display: grid;\n      gap: 22px;\n      align-content: space-between;\n      min-height: 510px;\n    }\n\n    .progress {\n      height: 8px;\n      background: #ecede8;\n      border-radius: 999px;\n      overflow: hidden;\n    }\n\n    .progress span {\n      display: block;\n      height: 100%;\n      width: var(--progress);\n      background: linear-gradient(90deg, var(--green), var(--gold));\n      border-radius: inherit;\n    }\n\n    .step {\n      display: none;\n      gap: 16px;\n    }\n\n    .step.active {\n      display: grid;\n    }\n\n    .choice-grid {\n      display: grid;\n      gap: 10px;\n    }\n\n    .choice,\n    .checkline {\n      min-height: 54px;\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      font-weight: 800;\n      text-align: left;\n    }\n\n    .choice.selected {\n      border-color: var(--green);\n      background: var(--green-soft);\n    }\n\n    .choice .icon,\n    .checkline .icon {\n      width: 32px;\n      height: 32px;\n      border-radius: 8px;\n      display: grid;\n      place-items: center;\n      background: #f0f4ed;\n      flex: 0 0 auto;\n    }\n\n    .checkline input {\n      width: 18px;\n      height: 18px;\n      accent-color: var(--green);\n      flex: 0 0 auto;\n    }\n\n    .fields {\n      display: grid;\n      gap: 12px;\n    }\n\n    label.field {\n      display: grid;\n      gap: 6px;\n      font-weight: 850;\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    input[type=\"text\"],\n    input[type=\"number\"],\n    select {\n      width: 100%;\n      min-height: 48px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 11px 12px;\n      background: #fff;\n      color: var(--ink);\n      outline-color: var(--green);\n    }\n\n    .actions {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      flex-wrap: wrap;\n    }\n\n    .btn {\n      min-height: 44px;\n      border-radius: 8px;\n      padding: 10px 14px;\n      font-weight: 900;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      background: var(--ink);\n      color: #fff;\n    }\n\n    .btn.secondary {\n      color: var(--ink);\n      background: #fff;\n      border: 1px solid var(--line);\n    }\n\n    .btn.green {\n      background: var(--green);\n    }\n\n    .btn.danger {\n      background: var(--red);\n    }\n\n    .section-head {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 14px;\n      margin-bottom: 16px;\n    }\n\n    .section-head p {\n      margin-top: 6px;\n      max-width: 68ch;\n    }\n\n    .settings-layout {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) minmax(260px, .55fr);\n      gap: 14px;\n      align-items: start;\n    }\n\n    .settings-form,\n    .danger-zone {\n      padding: 18px;\n      display: grid;\n      gap: 16px;\n    }\n\n    .settings-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 14px;\n    }\n\n    .settings-form .btn,\n    .danger-zone .btn {\n      justify-self: start;\n    }\n\n    .danger-zone {\n      border-color: rgba(188, 61, 53, .35);\n    }\n\n    .danger-zone p {\n      line-height: 1.55;\n    }\n\n    .grid {\n      display: grid;\n      gap: 12px;\n    }\n\n    .market-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 12px;\n    }\n\n    .category {\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      overflow: hidden;\n    }\n\n    .category-head {\n      padding: 13px 14px;\n      border-bottom: 1px solid var(--line);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      background: #fafbf8;\n    }\n\n    .asset-list {\n      display: grid;\n    }\n\n    .asset {\n      min-height: 60px;\n      display: grid;\n      grid-template-columns: 6px minmax(0, 1fr) auto;\n      gap: 12px;\n      align-items: center;\n      padding: 10px 12px 10px 0;\n      border-bottom: 1px solid #eef0eb;\n    }\n\n    .asset.has-chart {\n      cursor: pointer;\n    }\n\n    .asset.has-chart:hover {\n      background: #fafbf8;\n    }\n\n    .asset.has-chart strong::after {\n      content: \" chart\";\n      margin-left: 7px;\n      color: var(--muted);\n      font-size: 11px;\n      font-weight: 900;\n      text-transform: uppercase;\n    }\n\n    .asset:last-child {\n      border-bottom: 0;\n    }\n\n    .asset.can .marker { background: var(--green); }\n    .asset.cant .marker { background: var(--red); }\n    .marker {\n      width: 6px;\n      height: 100%;\n      border-radius: 0 999px 999px 0;\n      align-self: stretch;\n    }\n\n    .asset strong {\n      display: block;\n      line-height: 1.2;\n      overflow-wrap: anywhere;\n    }\n\n    .asset small {\n      color: var(--muted);\n      font-weight: 750;\n    }\n\n    .asset-action {\n      min-width: 84px;\n      min-height: 36px;\n      border-radius: 8px;\n      font-weight: 900;\n      padding: 8px 10px;\n      white-space: nowrap;\n    }\n\n    .asset-actions {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(70px, 1fr));\n      gap: 6px;\n    }\n\n    .asset-action.buy {\n      background: var(--green-soft);\n      color: var(--green);\n    }\n\n    .asset-action.sell {\n      background: var(--red-soft);\n      color: var(--red);\n    }\n\n    .asset-action.hold {\n      background: var(--red-soft);\n      color: var(--red);\n    }\n\n    .asset-action.forge {\n      background: #e3f0f2;\n      color: var(--teal);\n      text-decoration: none;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .market-chart {\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 14px;\n      margin-bottom: 12px;\n    }\n\n    .market-chart-head {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 12px;\n      margin-bottom: 10px;\n    }\n\n    .market-chart h3 {\n      font-size: 18px;\n      margin-bottom: 4px;\n    }\n\n    .quote-price {\n      text-align: right;\n      font-weight: 950;\n      font-size: 20px;\n      white-space: nowrap;\n    }\n\n    .quote-change.up { color: var(--green); }\n    .quote-change.down { color: var(--red); }\n\n    .range-row {\n      display: flex;\n      gap: 6px;\n      flex-wrap: wrap;\n      margin: 10px 0;\n    }\n\n    .range-btn {\n      min-width: 48px;\n      min-height: 34px;\n      border-radius: 8px;\n      border: 1px solid var(--line);\n      background: #fff;\n      color: var(--ink);\n      font-weight: 950;\n      padding: 6px 9px;\n    }\n\n    .range-btn.active {\n      background: var(--ink);\n      color: #fff;\n      border-color: var(--ink);\n    }\n\n    .symbol-search {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) auto;\n      gap: 8px;\n      margin-top: 10px;\n    }\n\n    .symbol-search input {\n      min-height: 44px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 10px 12px;\n      font-weight: 850;\n      outline-color: var(--green);\n    }\n\n    .chart-box {\n      position: relative;\n      height: 260px;\n      border: 1px solid #eef0eb;\n      border-radius: 8px;\n      background: linear-gradient(180deg, #fbfcfa, #fff);\n      overflow: hidden;\n    }\n\n    .chart-box svg {\n      display: block;\n      width: 100%;\n      height: 100%;\n      overflow: hidden;\n    }\n\n    .chart-hover-line {\n      stroke: rgba(38, 47, 35, .3);\n      stroke-width: 2;\n      vector-effect: non-scaling-stroke;\n      pointer-events: none;\n      opacity: 0;\n    }\n\n    .chart-tooltip {\n      position: absolute;\n      top: 12px;\n      min-width: 132px;\n      border-radius: 8px;\n      background: rgba(38, 47, 35, .94);\n      color: #fff;\n      padding: 8px 10px;\n      font-size: 12px;\n      font-weight: 850;\n      line-height: 1.35;\n      box-shadow: 0 12px 30px rgba(15, 23, 42, .22);\n      pointer-events: none;\n      opacity: 0;\n      z-index: 3;\n    }\n\n    .chart-tooltip strong {\n      display: block;\n      font-size: 14px;\n    }\n\n    .chart-box.hovering .chart-hover-line,\n    .chart-box.hovering .chart-tooltip {\n      opacity: 1;\n    }\n\n    .chart-empty {\n      min-height: 120px;\n      display: grid;\n      place-items: center;\n      color: var(--muted);\n      font-weight: 850;\n      text-align: center;\n      padding: 18px;\n    }\n\n    .chart-actions {\n      display: flex;\n      justify-content: flex-end;\n      gap: 8px;\n      flex-wrap: wrap;\n      margin-top: 10px;\n    }\n\n    .market-info {\n      margin-top: 12px;\n      padding-top: 12px;\n      border-top: 1px solid var(--line);\n    }\n\n    .market-info h4 {\n      margin-bottom: 8px;\n      font-size: 15px;\n    }\n\n    .market-info-grid {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 8px;\n    }\n\n    .market-info-item {\n      min-width: 0;\n      padding: 9px 10px;\n      border: 1px solid #eef0eb;\n      border-radius: 8px;\n      background: #fafbf8;\n    }\n\n    .market-info-item span {\n      display: block;\n      color: var(--muted);\n      font-size: 11px;\n      font-weight: 850;\n      line-height: 1.2;\n    }\n\n    .market-info-item strong {\n      display: block;\n      margin-top: 4px;\n      overflow-wrap: anywhere;\n      font-size: 13px;\n    }\n\n    #dashboard.trade-focus .shell {\n      display: none;\n    }\n\n    .trade-page {\n      min-height: calc(100vh - 92px);\n      display: grid;\n      place-items: center;\n      padding: 24px;\n    }\n\n    .trade-card {\n      width: min(620px, 100%);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fff;\n      padding: clamp(20px, 4vw, 36px);\n      box-shadow: var(--shadow);\n    }\n\n    .trade-card h2 {\n      margin-bottom: 6px;\n      font-size: clamp(24px, 4vw, 34px);\n    }\n\n    .trade-mode-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 8px;\n      margin: 22px 0;\n    }\n\n    .trade-mode {\n      min-height: 44px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fff;\n      color: var(--ink);\n      font-weight: 900;\n      padding: 8px 10px;\n    }\n\n    .trade-mode.active {\n      border-color: var(--green);\n      background: var(--green-soft);\n      color: var(--green);\n    }\n\n    .trade-amount-label {\n      display: block;\n      color: var(--muted);\n      font-size: 13px;\n      font-weight: 850;\n    }\n\n    .trade-amount {\n      width: 100%;\n      min-height: 48px;\n      margin-top: 8px;\n      border: 0;\n      border-bottom: 2px solid var(--ink);\n      border-radius: 0;\n      outline-color: var(--green);\n      padding: 8px 2px;\n      font-size: 24px;\n      font-weight: 900;\n    }\n\n    .trade-confirm {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n      margin-top: 28px;\n    }\n\n    .banner {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      gap: 12px;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fff;\n      margin-bottom: 12px;\n    }\n\n    .banner.good {\n      border-color: rgba(22, 138, 88, .45);\n      background: var(--green-soft);\n    }\n\n    .learn-grid {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) 270px;\n      gap: 12px;\n    }\n\n    [data-panel=\"learn\"].lesson-mode .learn-grid {\n      grid-template-columns: 1fr;\n    }\n\n    [data-panel=\"learn\"].lesson-mode .course-summary,\n    [data-panel=\"learn\"].lesson-mode #coursePath,\n    [data-panel=\"learn\"].lesson-mode .learn-grid > aside {\n      display: none;\n    }\n\n    .reward-list {\n      display: grid;\n      gap: 9px;\n    }\n\n    .reward {\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      gap: 8px;\n      grid-template-columns: minmax(0, 1fr) auto;\n      align-items: center;\n    }\n\n    .reward strong {\n      overflow-wrap: anywhere;\n    }\n\n    .course-summary {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .course-stat {\n      min-height: 78px;\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      align-content: center;\n      gap: 4px;\n    }\n\n    .course-path {\n      display: grid;\n      gap: 10px;\n      margin-top: 12px;\n    }\n\n    .course-node {\n      min-height: 76px;\n      width: 100%;\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      grid-template-columns: 42px minmax(0, 1fr) auto;\n      gap: 12px;\n      align-items: center;\n      color: var(--ink);\n      text-align: left;\n    }\n\n    .course-node.done {\n      background: var(--green-soft);\n      border-color: rgba(22, 138, 88, .35);\n    }\n\n    .course-node.current {\n      border-color: rgba(201, 137, 24, .8);\n      box-shadow: 0 12px 28px rgba(201, 137, 24, .18);\n    }\n\n    .course-node.locked {\n      background: #f4f5f1;\n      color: var(--muted);\n    }\n\n    .node-icon {\n      width: 42px;\n      height: 42px;\n      border-radius: 8px;\n      background: #f0f4ed;\n      display: grid;\n      place-items: center;\n      font-weight: 950;\n    }\n\n    .course-node.done .node-icon {\n      background: var(--green);\n      color: #fff;\n    }\n\n    .course-node.current .node-icon {\n      background: var(--gold-soft);\n      color: #7b5107;\n    }\n\n    .lesson-card {\n      padding: 14px;\n      display: grid;\n      gap: 14px;\n    }\n\n    .lesson-body {\n      line-height: 1.55;\n      color: var(--muted);\n    }\n\n    .module-status {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n\n    .mini-pill {\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 999px;\n      padding: 6px 10px;\n      font-size: 12px;\n      font-weight: 900;\n      color: var(--muted);\n    }\n\n    .mini-pill.done {\n      border-color: rgba(22, 138, 88, .35);\n      background: var(--green-soft);\n      color: var(--green);\n    }\n\n    .question-meta {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      flex-wrap: wrap;\n    }\n\n    .lesson-step {\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      gap: 10px;\n    }\n\n    .result-summary {\n      border: 1px solid rgba(22, 138, 88, .35);\n      background: var(--green-soft);\n      border-radius: 8px;\n      padding: 18px;\n      display: grid;\n      gap: 16px;\n    }\n\n    .result-grid {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .result-stat {\n      min-height: 92px;\n      border: 1px solid rgba(22, 138, 88, .25);\n      background: #fff;\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      align-content: center;\n      gap: 4px;\n    }\n\n    .result-stat span {\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 850;\n    }\n\n    .result-stat strong {\n      color: var(--ink);\n      font-size: 24px;\n      line-height: 1.1;\n    }\n\n    .miss-panel {\n      border: 1px solid rgba(188, 61, 53, .45);\n      background: var(--red-soft);\n      border-radius: 8px;\n      padding: 12px;\n      display: grid;\n      gap: 8px;\n    }\n\n    .miss-panel details {\n      background: #fff;\n      border: 1px solid rgba(188, 61, 53, .25);\n      border-radius: 8px;\n      padding: 10px;\n    }\n\n    .quiz-options {\n      display: grid;\n      gap: 9px;\n    }\n\n    .quiz-option {\n      min-height: 48px;\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 10px 12px;\n      text-align: left;\n      font-weight: 850;\n      color: var(--ink);\n    }\n\n    .quiz-option.correct {\n      border-color: rgba(22, 138, 88, .55);\n      background: var(--green-soft);\n    }\n\n    .quiz-option.wrong {\n      border-color: rgba(188, 61, 53, .55);\n      background: var(--red-soft);\n    }\n\n    .xp {\n      background: var(--gold-soft);\n      color: #7b5107;\n      border-radius: 999px;\n      padding: 6px 10px;\n      font-weight: 950;\n      white-space: nowrap;\n    }\n\n    .task-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 12px;\n    }\n\n    .task {\n      min-height: 210px;\n      padding: 14px;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      gap: 14px;\n    }\n\n    .task.bronze { border-top: 5px solid #a2642a; }\n    .task.silver { border-top: 5px solid #8b98a5; }\n    .task.gold { border-top: 5px solid var(--gold); }\n\n    .task h3 {\n      font-size: 18px;\n    }\n\n    .task-work {\n      width: 100%;\n      min-height: 74px;\n      resize: vertical;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 9px 10px;\n      outline-color: var(--green);\n      font: inherit;\n      font-size: 13px;\n    }\n\n    .task-complete {\n      display: grid;\n      gap: 8px;\n    }\n\n    .task-done {\n      color: var(--green);\n      font-weight: 900;\n    }\n\n    .difficulty {\n      display: inline-flex;\n      width: fit-content;\n      border-radius: 999px;\n      padding: 5px 9px;\n      font-size: 12px;\n      font-weight: 900;\n      background: #f0f4ed;\n      color: var(--muted);\n      text-transform: uppercase;\n    }\n\n    .streak-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 9px;\n    }\n\n    .streak {\n      min-height: 76px;\n      border: 1px solid var(--line);\n      background: #fff;\n      border-radius: 8px;\n      padding: 10px;\n      display: grid;\n      align-content: center;\n      gap: 4px;\n    }\n\n    .streak.claimed {\n      background: var(--green-soft);\n      border-color: rgba(22, 138, 88, .35);\n    }\n\n    .toast {\n      position: fixed;\n      left: 50%;\n      bottom: 18px;\n      transform: translateX(-50%) translateY(120px);\n      background: var(--ink);\n      color: #fff;\n      border-radius: 8px;\n      padding: 12px 14px;\n      font-weight: 850;\n      box-shadow: var(--shadow);\n      transition: transform .22s ease;\n      z-index: 5;\n      max-width: min(480px, calc(100vw - 32px));\n    }\n\n    .toast.show {\n      transform: translateX(-50%) translateY(0);\n    }\n\n    .hidden {\n      display: none !important;\n    }\n\n    @media (max-width: 920px) {\n      .shell,\n      .learn-grid,\n      .onboarding-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .side {\n        position: static;\n      }\n\n      .tabbar {\n        grid-template-columns: repeat(4, minmax(0, 1fr));\n      }\n\n      .tab {\n        justify-content: center;\n      }\n\n      #dashboard.lesson-focus .shell {\n        grid-template-columns: 1fr;\n      }\n\n      #dashboard.lesson-focus .side {\n        position: static;\n        padding: 6px;\n      }\n\n      #dashboard.lesson-focus .side .tabbar {\n        grid-template-columns: repeat(4, minmax(0, 1fr));\n      }\n\n      #dashboard.lesson-focus .side .tab {\n        min-height: 44px;\n      }\n\n      #dashboard.lesson-focus .side .tab-label {\n        display: inline;\n      }\n\n      #dashboard.lesson-focus .side .tab-icon {\n        font-size: inherit;\n      }\n\n      .onboard-art {\n        min-height: 230px;\n      }\n\n      .onboard-content {\n        min-height: auto;\n      }\n    }\n\n    @media (max-width: 760px) {\n      .app {\n        width: min(100% - 20px, 1180px);\n        padding-top: 14px;\n      }\n\n      .topbar,\n      .section-head,\n      .market-chart-head,\n      .banner {\n        align-items: stretch;\n        flex-direction: column;\n      }\n\n      .pillrow {\n        justify-content: flex-start;\n      }\n\n      .market-grid,\n      .course-summary,\n      .task-grid,\n      .streak-grid,\n      .settings-layout,\n      .settings-grid,\n      .result-grid,\n      .market-info-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .course-node {\n        grid-template-columns: 42px minmax(0, 1fr);\n      }\n\n      .course-node .xp {\n        grid-column: 2;\n        width: fit-content;\n      }\n\n      .asset {\n        grid-template-columns: 6px minmax(0, 1fr);\n      }\n\n      .symbol-search {\n        grid-template-columns: 1fr;\n      }\n\n      .quote-price {\n        text-align: left;\n      }\n\n      .asset-action,\n      h1 { font-size: 24px; }\n      h2 { font-size: 21px; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"app\" id=\"app\">\n    <div class=\"onboarding-wrap\" id=\"onboarding\">\n      <section class=\"onboarding\" aria-label=\"Setup\">\n        <div class=\"onboarding-grid\">\n          <aside class=\"onboard-art\">\n            <div>\n              <div class=\"logo\">IQ</div>\n              <h1 style=\"margin-top:16px\">Invest Quest</h1>\n              <p style=\"margin-top:8px;color:rgba(255,255,255,.86)\">Practice investing, earn XP, and learn what each market is before touching real money.</p>\n            </div>\n            <div class=\"mini-chart\" aria-hidden=\"true\">\n              <span></span><span></span><span></span><span></span><span></span>\n            </div>\n          </aside>\n          <main class=\"onboard-content\">\n            <div class=\"progress\" aria-label=\"Setup progress\"><span id=\"progressBar\"></span></div>\n\n            <section class=\"step active\" data-step=\"0\">\n              <div>\n                <h2>Why are you investing?</h2>\n                <p class=\"muted\" style=\"margin-top:8px\">Pick the reason that fits best today.</p>\n              </div>\n              <div class=\"choice-grid\" data-choice-group=\"reason\">\n                <button class=\"choice\" data-value=\"Learn the basics\"><span class=\"icon\">A</span><span>Learn the basics</span></button>\n                <button class=\"choice\" data-value=\"Build long-term wealth\"><span class=\"icon\">Y</span><span>Build long-term wealth</span></button>\n                <button class=\"choice\" data-value=\"Practice trading\"><span class=\"icon\">T</span><span>Practice trading</span></button>\n                <button class=\"choice\" data-value=\"Understand the news\"><span class=\"icon\">N</span><span>Understand the news</span></button>\n              </div>\n            </section>\n\n            <section class=\"step\" data-step=\"1\">\n              <div>\n                <h2>How old are you?</h2>\n                <p class=\"muted\" style=\"margin-top:8px\">Age changes the learning tone, not your score.</p>\n              </div>\n              <div class=\"fields\">\n                <label class=\"field\">Age <input id=\"ageInput\" type=\"number\" min=\"1\" max=\"120\" placeholder=\"Enter age\"></label>\n              </div>\n            </section>\n\n            <section class=\"step\" data-step=\"2\">\n              <div>\n                <h2>Last, First name</h2>\n                <p class=\"muted\" style=\"margin-top:8px\">Your dashboard will use this name.</p>\n              </div>\n              <div class=\"fields\">\n                <label class=\"field\">Last name <input id=\"lastInput\" type=\"text\" autocomplete=\"family-name\" placeholder=\"Last\"></label>\n                <label class=\"field\">First name <input id=\"firstInput\" type=\"text\" autocomplete=\"given-name\" placeholder=\"First\"></label>\n              </div>\n            </section>\n\n            <section class=\"step\" data-step=\"3\">\n              <div>\n                <h2>How good are you?</h2>\n                <p class=\"muted\" style=\"margin-top:8px\">Pick your starting level.</p>\n              </div>\n              <div class=\"choice-grid\" data-choice-group=\"level\">\n                <button class=\"choice\" data-value=\"Beginner\"><span class=\"icon\">1</span><span>Beginner</span></button>\n                <button class=\"choice\" data-value=\"Intermediate\"><span class=\"icon\">2</span><span>Intermediate</span></button>\n                <button class=\"choice\" data-value=\"Expert\"><span class=\"icon\">3</span><span>Expert</span></button>\n              </div>\n            </section>\n\n            <div class=\"actions\">\n              <button class=\"btn secondary\" id=\"backBtn\" type=\"button\">Back</button>\n              <button class=\"btn green\" id=\"nextBtn\" type=\"button\">Next</button>\n            </div>\n          </main>\n        </div>\n      </section>\n    </div>\n\n    <div id=\"dashboard\" class=\"hidden\">\n      <header class=\"topbar\">\n        <div class=\"brand\">\n          <div class=\"logo\">IQ</div>\n          <div>\n            <h1>Invest Quest</h1>\n            <p class=\"muted\" id=\"welcomeLine\">Welcome</p>\n          </div>\n        </div>\n        <div class=\"pillrow\">\n          <span class=\"pill\">XP <span id=\"xpTotal\">0</span></span>\n          <span class=\"pill\">Streak <span id=\"streakTotal\">0</span></span>\n          <span class=\"pill\">Level <span id=\"levelName\">Beginner</span></span>\n        </div>\n      </header>\n\n      <div class=\"shell\">\n        <aside class=\"side\">\n          <div class=\"hero-art\" aria-hidden=\"true\"><div class=\"bars\"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div></div>\n          <nav class=\"tabbar\" aria-label=\"App sections\">\n            <button class=\"tab active\" data-tab=\"markets\" title=\"Markets\" aria-label=\"Markets\"><span class=\"tab-icon\" aria-hidden=\"true\">📈</span><span class=\"tab-label\">Markets</span></button>\n            <button class=\"tab\" data-tab=\"learn\" title=\"Learn\" aria-label=\"Learn\"><span class=\"tab-icon\" aria-hidden=\"true\">📚</span><span class=\"tab-label\">Learn</span></button>\n            <button class=\"tab\" data-tab=\"tasks\" title=\"Tasks\" aria-label=\"Tasks\"><span class=\"tab-icon\" aria-hidden=\"true\">🏆</span><span class=\"tab-label\">Tasks</span></button>\n            <button class=\"tab\" data-tab=\"settings\" title=\"Settings\" aria-label=\"Settings\"><span class=\"tab-icon\" aria-hidden=\"true\">⚙</span><span class=\"tab-label\">Settings</span></button>\n          </nav>\n          <div class=\"legend\">\n            <div class=\"legend-item\"><span class=\"stripe red\"></span><span>Can’t buy, holding economy</span></div>\n            <div class=\"legend-item\"><span class=\"stripe green\"></span><span>Can buy</span></div>\n          </div>\n        </aside>\n\n        <main class=\"mainpanel\">\n          <section data-panel=\"markets\">\n            <div class=\"section-head\">\n              <div>\n                <h2>Stock markets, crypto, and paper choices</h2>\n                <p class=\"muted\">Buy and sell are practice actions for learning the markets.</p>\n              </div>\n            </div>\n            <div class=\"market-chart\" id=\"marketChart\"></div>\n            <div class=\"market-grid\" id=\"marketGrid\"></div>\n          </section>\n\n          <section data-panel=\"learn\" class=\"hidden\">\n            <div class=\"section-head\">\n              <div>\n                <h2>Learning course</h2>\n                <p class=\"muted\">Finish lessons, quizzes, and tests to unlock the next step and earn XP automatically.</p>\n              </div>\n              <button class=\"btn green\" id=\"dailyBtn\">Daily login +10 XP</button>\n            </div>\n            <div class=\"learn-grid\">\n              <div class=\"grid\">\n                <div class=\"course-summary\">\n                  <div class=\"course-stat\"><strong id=\"courseDone\">0/0</strong><span class=\"muted\">Steps done</span></div>\n                  <div class=\"course-stat\"><strong id=\"coursePercent\">0%</strong><span class=\"muted\">Course progress</span></div>\n                  <div class=\"course-stat\"><strong id=\"courseNext\">Lesson 1</strong><span class=\"muted\">Next up</span></div>\n                </div>\n                <div class=\"card lesson-card\" id=\"lessonPanel\"></div>\n                <div class=\"course-path\" id=\"coursePath\"></div>\n              </div>\n              <aside class=\"grid\">\n                <div class=\"card\" style=\"padding:14px\">\n                  <h3>Automatic XP</h3>\n                  <p class=\"muted\" style=\"margin-top:6px\">Half of lesson, quiz, and test XP comes from accuracy. Half comes from time, with 1 XP removed for each second after 2 minutes.</p>\n                </div>\n                <div class=\"card\" style=\"padding:14px\">\n                  <h3>Streak rewards</h3>\n                  <p class=\"muted\" style=\"margin-top:6px\">Claim when your learning streak reaches the milestone.</p>\n                  <div class=\"streak-grid\" id=\"streakGrid\" style=\"margin-top:12px\"></div>\n                </div>\n                <div class=\"card\" style=\"padding:14px\">\n                  <h3>Streak Freeze</h3>\n                  <p class=\"muted\" style=\"margin-top:6px\">Protect one missed day.</p>\n                  <button class=\"btn secondary\" id=\"freezeBtn\" style=\"margin-top:12px;width:100%\">Buy freeze -250 XP</button>\n                </div>\n              </aside>\n            </div>\n          </section>\n\n          <section data-panel=\"tasks\" class=\"hidden\">\n            <div class=\"section-head\">\n              <div>\n                <h2>Bronze, Silver, Gold tasks</h2>\n                <p class=\"muted\" id=\"taskGuide\">Three daily goals: one Bronze, one Silver, and one Gold.</p>\n              </div>\n            </div>\n            <div class=\"task-grid\" id=\"taskGrid\"></div>\n          </section>\n\n          <section data-panel=\"settings\" class=\"hidden\">\n            <div class=\"section-head\">\n              <div>\n                <h2>Settings</h2>\n                <p class=\"muted\">Update your profile or start over with a new account.</p>\n              </div>\n            </div>\n            <div class=\"settings-layout\">\n              <form class=\"card settings-form\" id=\"settingsForm\">\n                <h3>Profile</h3>\n                <div class=\"settings-grid\">\n                  <label class=\"field\">First name\n                    <input id=\"settingsFirst\" type=\"text\" autocomplete=\"given-name\" required>\n                  </label>\n                  <label class=\"field\">Last name\n                    <input id=\"settingsLast\" type=\"text\" autocomplete=\"family-name\" required>\n                  </label>\n                  <label class=\"field\">Age\n                    <input id=\"settingsAge\" type=\"number\" min=\"1\" max=\"120\" required>\n                  </label>\n                  <label class=\"field\">Level\n                    <select id=\"settingsLevel\">\n                      <option value=\"Beginner\">Beginner</option>\n                      <option value=\"Intermediate\">Intermediate</option>\n                      <option value=\"Expert\">Expert</option>\n                    </select>\n                  </label>\n                </div>\n                <button class=\"btn green\" type=\"submit\">Save changes</button>\n              </form>\n              <div class=\"card danger-zone\">\n                <h3>Reset account</h3>\n                <p class=\"muted\">This deletes your profile, XP, streak, course progress, and completed tasks. It cannot be undone.</p>\n                <button class=\"btn danger\" id=\"resetAccountBtn\" type=\"button\">Reset account</button>\n              </div>\n            </div>\n          </section>\n        </main>\n      </div>\n      <section id=\"tradePage\" class=\"trade-page hidden\" aria-live=\"polite\"></section>\n    </div>\n  </div>\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script>\n    const markets = [\n      { category: \"Crypto\", icon: \"₿\", items: [\n        [\"Bitcoin\", \"can\", \"Crypto\", \"BTC-USD\"],\n        [\"Ethereum\", \"can\", \"Crypto\", \"ETH-USD\"],\n        [\"Dogecoin\", \"can\", \"Crypto\", \"DOGE-USD\"]\n      ]},\n      { category: \"National\", icon: \"US\", items: [\n        [\"S&P 500\", \"cant\", \"Market index\", \"SPY\"],\n        [\"Dow 30\", \"cant\", \"Market index\", \"DIA\"],\n        [\"Russell 2000\", \"cant\", \"Market index\", \"IWM\"],\n        [\"Nasdaq\", \"cant\", \"Market index\", \"QQQ\"],\n        [\"Vanguard S&P 500 ETF (VOO)\", \"can\", \"ETF\", \"VOO\"],\n        [\"Berkshire Hathaway\", \"can\", \"Stock\", \"BRK-B\"],\n        [\"QQQ\", \"can\", \"ETF\", \"QQQ\"],\n        [\"Gold\", \"can\", \"ETF\", \"GLD\"],\n        [\"VIX\", \"cant\", \"Volatility index\", \"^VIX\"],\n        [\"SpaceX\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/spacex_stock/\"],\n        [\"Tesla, Inc.\", \"can\", \"Stock\", \"TSLA\"]\n      ]},\n      { category: \"Penny markets\", icon: \"¢\", items: [\n        [\"AMC\", \"can\", \"High-risk stock\", \"AMC\"],\n        [\"BMBL\", \"can\", \"High-risk stock\", \"BMBL\"],\n        [\"GNIS\", \"can\", \"High-risk stock\", \"GNIS\"],\n        [\"SMRT\", \"can\", \"High-risk stock\", \"SMRT\"],\n        [\"DPLS\", \"can\", \"High-risk stock\", \"DPLS\"]\n      ]},\n      { category: \"Private stocks\", icon: \"P\", items: [\n        [\"Anthropic\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/anthropic_stock/\"],\n        [\"OpenAI\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/openai_stock/\"],\n        [\"Perplexity\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/perplexity_stock/\"],\n        [\"Skild AI\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/skild-ai_stock/\"],\n        [\"Discord\", \"cant\", \"Private company - Forge\", \"\", \"https://forgeglobal.com/discord_stock/\"]\n      ]},\n      { category: \"International\", icon: \"🌐\", items: [\n        [\"Nikkei 225\", \"cant\", \"Index tracker\", \"^N225\"],\n        [\"STOXX Europe 600\", \"cant\", \"Index tracker\", \"^STOXX\"],\n        [\"FTSE 100\", \"cant\", \"Index tracker\", \"^FTSE\"],\n        [\"Hang Seng\", \"cant\", \"Index tracker\", \"^HSI\"],\n        [\"^XDN\", \"cant\", \"Index tracker\", \"^XDN\"],\n        [\"DAX\", \"cant\", \"Index tracker\", \"^GDAXI\"],\n        [\"Shanghai Composite\", \"cant\", \"Index tracker\", \"000001.SS\"],\n        [\"KOSPI\", \"cant\", \"Index tracker\", \"^KS11\"],\n        [\"Toyota Motor Corporation\", \"can\", \"Stock\", \"TM\"],\n        [\"Alibaba Group Holding\", \"can\", \"Stock\", \"BABA\"],\n        [\"Tencent Holdings\", \"can\", \"Stock\", \"TCEHY\"],\n        [\"Nestlé\", \"can\", \"Stock\", \"NSRGY\"],\n        [\"Taiwan Semiconductor Manufacturing Company\", \"can\", \"Stock\", \"TSM\"],\n        [\"Samsung Electronics\", \"can\", \"Stock\", \"005930.KS\"],\n        [\"Nintendo\", \"can\", \"Stock\", \"NTDOY\"],\n        [\"Sony Group Corporation\", \"can\", \"Stock\", \"SONY\"],\n        [\"Baidu\", \"can\", \"Stock\", \"BIDU\"],\n        [\"NetEase\", \"can\", \"Stock\", \"NTES\"],\n        [\"Hermès\", \"can\", \"Stock\", \"HESAY\"],\n        [\"L'Oréal\", \"can\", \"Stock\", \"LRLCY\"],\n        [\"Novo Nordisk\", \"can\", \"Stock\", \"NVO\"]\n      ]}\n    ];\n\n    const moduleTopics = [\n      [\"Market Basics\", \"markets\", \"how buying, selling, prices, and practice trades work\"],\n      [\"Stocks\", \"stocks\", \"how company ownership, prices, and risk connect\"],\n      [\"Indexes and ETFs\", \"indexes\", \"how baskets like the S&P 500 and QQQ track groups\"],\n      [\"Crypto\", \"crypto\", \"why Bitcoin, Ethereum, and Dogecoin move differently\"],\n      [\"Risk and Reward\", \"risk\", \"how to compare possible gains with possible losses\"],\n      [\"National Markets\", \"national markets\", \"how US indexes and companies fit together\"],\n      [\"International Markets\", \"international markets\", \"how global companies and indexes move\"],\n      [\"Penny Markets\", \"penny markets\", \"why smaller risky stocks need extra care\"],\n      [\"Private Companies\", \"private companies\", \"why some famous companies are watch-only\"],\n      [\"Paper Trading\", \"paper trading\", \"how to practice trades without real money\"],\n      [\"Portfolio Building\", \"portfolios\", \"how to combine different assets in a plan\"],\n      [\"Review and Strategy\", \"strategy\", \"how to make a careful learning plan\"]\n    ];\n\n    const courseModules = moduleTopics.map((topic, index) => buildModule(index + 1, topic));\n    const courseItems = buildCourseItems();\n\n    function buildModule(number, [title, shortName, focus]) {\n      const lessons = buildModuleLessons(number, title, shortName, focus);\n      return {\n        id: `module-${number}`,\n        kind: \"module\",\n        number,\n        title: `Module ${number}: ${title}`,\n        shortTitle: title,\n        focus,\n        lessonXp: 75,\n        quizXp: 60,\n        perfectXp: 15,\n        moduleXp: 150,\n        lessons,\n        lessonPages: lessons[0].pages,\n        skipQuestions: buildModuleSkipQuestions(number, lessons),\n        quizQuestions: [\n          ...buildMultipleChoiceQuestions(number, title, shortName, focus, 10),\n          ...buildSimulationQuestions(number, title, shortName, focus, 5)\n        ]\n      };\n    }\n\n    function buildModuleLessons(number, title, shortName, focus) {\n      const lessonTitles = [\n        \"Core ideas\",\n        \"Reading price moves\",\n        \"Evidence and sources\",\n        \"Downside risk\",\n        \"Comparing choices\",\n        \"News and reactions\",\n        \"Planning a trade\",\n        \"Keeping a journal\",\n        \"Portfolio fit\",\n        \"Reviewing the thesis\"\n      ];\n      return lessonTitles.map((lessonTitle, index) => ({\n        id: `module-${number}-lesson-${index + 1}`,\n        number: index + 1,\n        title: `Lesson ${index + 1}: ${lessonTitle}`,\n        pages: buildLessonPages(number, title, shortName, focus, index + 1, lessonTitle)\n      }));\n    }\n\n    function buildModuleSkipQuestions(number, lessons) {\n      const selected = lessons.flatMap((lesson, lessonIndex) => {\n        const practice = lesson.pages.filter(page => page.type === \"practice\");\n        const start = (number + lessonIndex) % practice.length;\n        return [0, 3, 6].map(offset => {\n          const page = practice[(start + offset) % practice.length];\n          return {\n            ...page,\n            sourceLesson: lesson.title\n          };\n        });\n      });\n      return selected\n        .map((question, index) => scrambleQuestion(question, `skip-${number}-${index}`))\n        .sort((a, b) => hashString(`skip-order-${number}-${a.prompt}`) - hashString(`skip-order-${number}-${b.prompt}`));\n    }\n\n    function hashString(value) {\n      let hash = 0;\n      for (let i = 0; i < value.length; i += 1) {\n        hash = (hash * 31 + value.charCodeAt(i)) >>> 0;\n      }\n      return hash;\n    }\n\n    function scrambleQuestion(question, seed) {\n      const balancedOptions = balanceOptionLengths(question, seed);\n      const correctOption = balancedOptions[question.answer];\n      const options = [...balancedOptions].sort((a, b) => hashString(`${seed}-${a}`) - hashString(`${seed}-${b}`));\n      return { ...question, options, answer: options.indexOf(correctOption) };\n    }\n\n    function balanceOptionLengths(question, seed) {\n      const targetLength = Math.max(...question.options.map(option => option.length));\n      const correctAddOns = [\n        \"with a clear reason.\",\n        \"using the stated facts.\",\n        \"as the lesson explains.\"\n      ];\n      const distractorAddOns = [\n        \"but leaves out a detail.\",\n        \"with incomplete logic.\",\n        \"without enough support.\",\n        \"using an unrelated reason.\"\n      ];\n      return question.options.map((option, index) => {\n        let balanced = option;\n        const addOns = index === question.answer ? correctAddOns : distractorAddOns;\n        let guard = 0;\n        while (balanced.length < targetLength - 12 && guard < 6) {\n          balanced = `${balanced} ${addOns[hashString(`${seed}-${index}-${guard}`) % addOns.length]}`;\n          guard += 1;\n        }\n        return balanced;\n      });\n    }\n\n    function moduleProfile(number, title, shortName, focus) {\n      const profiles = [\n        {\n          asset: \"a broad market paper trade\",\n          secondAsset: \"a single-company stock\",\n          event: \"buyers are active but the price keeps changing quickly\",\n          risk: \"the order could fill at a worse price than expected\",\n          signal: \"steady demand with a clear reason behind it\",\n          trap: \"treating any green chart as proof that the idea is safe\",\n          metric: \"price, reason for the move, and whether the trade still fits\"\n        },\n        {\n          asset: \"Tesla stock\",\n          secondAsset: \"Toyota stock\",\n          event: \"earnings are better than expected but costs also rose\",\n          risk: \"the company may grow while profits stay under pressure\",\n          signal: \"sales, margins, and management comments point the same way\",\n          trap: \"assuming a famous company is automatically a good trade\",\n          metric: \"revenue growth, profit margin, debt, and the original thesis\"\n        },\n        {\n          asset: \"QQQ\",\n          secondAsset: \"the S&P 500\",\n          event: \"tech stocks rise while the broader market is flat\",\n          risk: \"the basket may be concentrated in one sector\",\n          signal: \"the index move matches the companies that carry the most weight\",\n          trap: \"thinking every index is equally diversified\",\n          metric: \"holdings, sector concentration, fees, and tracking goal\"\n        },\n        {\n          asset: \"Ethereum\",\n          secondAsset: \"Bitcoin\",\n          event: \"crypto jumps after a regulation headline\",\n          risk: \"sentiment can reverse faster than the lesson can explain\",\n          signal: \"network use, regulation news, and liquidity support the move\",\n          trap: \"treating online excitement as the same thing as evidence\",\n          metric: \"volatility, news source, liquidity, and position size\"\n        },\n        {\n          asset: \"a high-reward paper trade\",\n          secondAsset: \"a steadier index fund\",\n          event: \"the possible gain is large but the downside is also large\",\n          risk: \"the reward looks exciting because the loss is being ignored\",\n          signal: \"the upside is paired with a clear downside and exit review\",\n          trap: \"thinking a bigger possible gain means a better plan\",\n          metric: \"reward, downside, probability, and what would change the thesis\"\n        },\n        {\n          asset: \"the Dow 30\",\n          secondAsset: \"the Russell 2000\",\n          event: \"large US companies rise while smaller companies fall\",\n          risk: \"one national headline may not affect every index the same way\",\n          signal: \"the move lines up with company size, sector mix, and the news\",\n          trap: \"treating all US market indexes as one identical market\",\n          metric: \"index makeup, sector weight, company size, and news fit\"\n        },\n        {\n          asset: \"Toyota Motor Corporation\",\n          secondAsset: \"Samsung Electronics\",\n          event: \"currency news changes how foreign profits look in dollars\",\n          risk: \"a good company can still be affected by currency and country risk\",\n          signal: \"company performance and local market conditions both support it\",\n          trap: \"forgetting that international returns can move for extra reasons\",\n          metric: \"currency, home market, company news, and global comparison\"\n        },\n        {\n          asset: \"AMC\",\n          secondAsset: \"BMBL\",\n          event: \"a penny-market name spikes after social-media attention\",\n          risk: \"low liquidity and hype can make exits harder than entries\",\n          signal: \"volume, news quality, and risk limits are checked together\",\n          trap: \"believing a cheap share price means the trade is cheap risk\",\n          metric: \"volume, spread, news source, dilution risk, and exit plan\"\n        },\n        {\n          asset: \"OpenAI as a watch-only company\",\n          secondAsset: \"Anthropic as a watch-only company\",\n          event: \"private-company news sounds exciting but shares are not public\",\n          risk: \"watch-only interest can be mistaken for a normal buy button\",\n          signal: \"business progress is studied without pretending it is tradable\",\n          trap: \"thinking a famous private company works like a public stock\",\n          metric: \"availability, competitors, revenue clues, and public alternatives\"\n        },\n        {\n          asset: \"a first paper trade\",\n          secondAsset: \"a watchlist idea\",\n          event: \"the practice trade wins even though the notes were weak\",\n          risk: \"a good outcome can hide a poor decision process\",\n          signal: \"the learner can explain the thesis before and after the result\",\n          trap: \"judging the plan only by whether the paper trade made XP\",\n          metric: \"entry reason, risk note, result, and review quality\"\n        },\n        {\n          asset: \"a portfolio with Tesla and crypto\",\n          secondAsset: \"a portfolio with QQQ and Toyota\",\n          event: \"several holdings move down together on the same day\",\n          risk: \"the portfolio may be less diversified than it looks\",\n          signal: \"each holding plays a different role in the plan\",\n          trap: \"counting many positions as diversification without checking overlap\",\n          metric: \"overlap, sector exposure, volatility, and role of each holding\"\n        },\n        {\n          asset: \"a final strategy plan\",\n          secondAsset: \"a random trade idea\",\n          event: \"new information challenges the original thesis\",\n          risk: \"the learner may defend the old idea instead of updating it\",\n          signal: \"the plan names what evidence would change the decision\",\n          trap: \"changing the story after every result to avoid being wrong\",\n          metric: \"thesis, evidence, risk trigger, review rule, and next step\"\n        }\n      ];\n      return { title, shortName, focus, ...profiles[number - 1] };\n    }\n\n    function moduleKnowledge(number) {\n      const knowledge = [\n        { term: \"market price\", definition: \"the current amount where buyers and sellers agree to trade\", example: \"a burst of buyers can lift a price when fewer sellers are available\", risk: \"a fast move can reverse when the news fades\", action: \"record the price, catalyst, and reason before practicing\", falseIdea: \"a green price always means the asset is a good buy\" },\n        { term: \"share of stock\", definition: \"a small ownership piece of a public company\", example: \"earnings can change demand for a company's shares\", risk: \"a strong brand does not remove business risk\", action: \"connect the price to the company business, not only its name\", falseIdea: \"one share gives control over every company decision\" },\n        { term: \"ETF\", definition: \"a fund that holds a basket of assets and trades like a stock\", example: \"QQQ gives exposure to many large Nasdaq companies in one trade\", risk: \"a basket can still fall when many holdings share the same sector\", action: \"identify what the fund holds before adding it to a portfolio\", falseIdea: \"an ETF cannot lose value because it owns many companies\" },\n        { term: \"crypto asset\", definition: \"a digital asset that can move quickly with demand, news, and regulation\", example: \"regulation news can change crypto prices within hours\", risk: \"sharp moves can happen even when the project itself is unchanged\", action: \"keep position size small enough to handle a large move\", falseIdea: \"a low-priced coin is automatically less risky than Bitcoin\" },\n        { term: \"risk-reward tradeoff\", definition: \"the relationship between a possible gain and a possible loss\", example: \"a large upside can still be a poor trade when the downside is too large\", risk: \"focusing only on upside can hide a loss that is hard to recover\", action: \"decide the maximum acceptable loss before entering a paper trade\", falseIdea: \"the largest possible return is always the best choice\" },\n        { term: \"market index\", definition: \"a number that tracks a group of stocks in one part of the market\", example: \"the S&P 500 can move when many large US companies react to the same news\", risk: \"an index move does not explain every individual stock\", action: \"separate broad-market news from company-specific news\", falseIdea: \"every stock in an index moves by the same percentage\" },\n        { term: \"international market\", definition: \"a market outside the learner's home country, often affected by local rules and currencies\", example: \"a currency change can affect a US investor's return on a foreign stock\", risk: \"news in another country can arrive when local markets are closed\", action: \"note the country, currency, and business exposure before practicing\", falseIdea: \"foreign stocks always move the same way as US stocks\" },\n        { term: \"penny market\", definition: \"a low-priced, high-risk stock that can be thinly traded\", example: \"social-media attention can make a thinly traded stock jump\", risk: \"wide spreads can make buying and selling cost more than expected\", action: \"treat a low share price as a risk question, not a bargain label\", falseIdea: \"a cheap share price means there is little money at risk\" },\n        { term: \"private company\", definition: \"a company whose shares are not normally bought on a public stock exchange\", example: \"a private company can be studied even when the standard Buy button is unavailable\", risk: \"a private-market value may be hard for most investors to access or sell\", action: \"use public competitors for practice when the company itself is watch-only\", falseIdea: \"a famous private company can be bought like any listed stock\" },\n        { term: \"paper trade\", definition: \"a simulated buy or sell used to practice without real cash\", example: \"a paper trade can reveal whether a plan was clear before money is at risk\", risk: \"a lucky paper result can hide a weak process\", action: \"record the entry reason, amount, risk, and later result\", falseIdea: \"paper trading makes risk management unnecessary\" },\n        { term: \"diversification\", definition: \"spreading a portfolio across different sources of risk\", example: \"a broad index and a bond fund can reduce reliance on one company\", risk: \"several tech holdings can still move together despite different names\", action: \"look for what each holding adds rather than counting tickers\", falseIdea: \"owning more tickers always creates diversification\" },\n        { term: \"investment thesis\", definition: \"a clear reason for an idea plus the facts that could prove it wrong\", example: \"a thesis can be updated when new evidence changes the original reason\", risk: \"changing the story only after a loss prevents learning\", action: \"write the reason, risk trigger, and review date before acting\", falseIdea: \"a thesis should never change once it is written\" }\n      ];\n      return knowledge[number - 1] || knowledge[0];\n    }\n\n    function lessonQuestionContext(lessonNumber) {\n      const contexts = [\n        { title: \"Core ideas\", focus: \"state the key term in plain language\", scenario: \"A learner wants to act because a price is green but cannot explain the market term in the lesson.\", move: \"Define the term in plain words and connect it to one clear example.\", mistake: \"Using a word as proof without knowing what it means.\", journal: \"Write the term, one example, and one open question.\", source: \"A post uses a market word but gives no example or definition.\" },\n        { title: \"Reading price moves\", focus: \"describe a price change without inventing its cause\", scenario: \"An asset rises 4 percent after the market opens, but no explanation is known yet.\", move: \"Record the price move as a fact and keep the cause unknown until evidence appears.\", mistake: \"Treating the first price move as proof of its cause.\", journal: \"Write the percentage move, time, and any known catalyst.\", source: \"A headline claims to know the reason for a move but names no source.\" },\n        { title: \"Evidence and sources\", focus: \"tell useful evidence from an unsupported claim\", scenario: \"A creator says a company will surge but gives no filing, data, or source.\", move: \"Mark it as an unproven claim and look for a source with facts.\", mistake: \"Treating confidence as the same as evidence.\", journal: \"State the claim, the source, the evidence, and what is missing.\", source: \"A post makes a strong prediction without a primary source.\" },\n        { title: \"Downside risk\", focus: \"name a specific downside before taking a position\", scenario: \"A learner likes the possible upside but cannot say what loss would change the plan.\", move: \"Set a loss limit and name the condition that would end the idea.\", mistake: \"Calling something risky without describing the actual risk.\", journal: \"Write the possible loss, trigger, and planned position size.\", source: \"A post lists rewards but hides the possible losses.\" },\n        { title: \"Comparing choices\", focus: \"choose based on the role each option plays\", scenario: \"Two assets look reasonable, but one adds the same risk the learner already owns.\", move: \"Choose based on the role and overlap in the portfolio plan.\", mistake: \"Picking the faster chart without considering the portfolio role.\", journal: \"Write what each option adds and what it overlaps.\", source: \"A post ranks assets by recent price alone.\" },\n        { title: \"News and reactions\", focus: \"separate a news event from a permanent business change\", scenario: \"A headline creates excitement before the full report is released.\", move: \"Wait for the full report and note which fact would make the news matter.\", mistake: \"Treating a headline as the final explanation.\", journal: \"Record the date, source, claimed effect, and missing facts.\", source: \"A post repeats a headline but links to nothing.\" },\n        { title: \"Planning a trade\", focus: \"turn an idea into a usable paper-trade plan\", scenario: \"A learner has an asset name but no entry, size, or reason.\", move: \"Write the entry reason, amount, risk limit, and review point.\", mistake: \"Calling an asset name a complete plan.\", journal: \"Keep the entry reason, amount, risk limit, and review rule.\", source: \"A post says to buy now with no time horizon.\" },\n        { title: \"Keeping a journal\", focus: \"record decisions so they can be reviewed\", scenario: \"A learner remembers a trade as smart but did not write why at the time.\", move: \"Record the original reason before the outcome changes memory.\", mistake: \"Writing a new explanation after the result is known.\", journal: \"Write the pre-trade reason, risk, result, and update.\", source: \"A post shares only a successful result with no original plan.\" },\n        { title: \"Portfolio fit\", focus: \"look at how positions work together\", scenario: \"A learner owns several technology companies and calls the portfolio diversified.\", move: \"Identify shared exposure and add a different source of risk if needed.\", mistake: \"Counting names instead of sources of risk.\", journal: \"List each holding's role and any shared exposure.\", source: \"A post says ten tickers automatically make a safe portfolio.\" },\n        { title: \"Reviewing the thesis\", focus: \"update an idea when facts change\", scenario: \"New evidence contradicts the reason a learner wrote before trading.\", move: \"Revise or close the idea based on the new fact.\", mistake: \"Protecting the old story after its reason disappears.\", journal: \"Record what changed and why the next step changed.\", source: \"A post keeps the same recommendation after key facts change.\" }\n      ];\n      return contexts[lessonNumber - 1] || contexts[0];\n    }\n\n    function buildPracticePages(number, title, shortName, focus, lessonNumber = 1, lessonTitle = \"Core ideas\") {\n      const profile = moduleProfile(number, title, shortName, focus);\n      const knowledge = moduleKnowledge(number);\n      const context = lessonQuestionContext(lessonNumber);\n      const units = 2 + (lessonNumber % 4);\n      const unitPrice = 7 + (number * 3) + lessonNumber;\n      const positionValue = units * unitPrice;\n      return [\n        {\n          type: \"practice\",\n          style: \"Concept\",\n          prompt: `Lesson ${lessonNumber}: What is the main skill in \"${context.title}\"?`,\n          options: [context.focus, `Memorize one asset name without using it.`, `Follow a chart without writing a reason.`, `Choose the most popular answer as quickly as possible.`],\n          answer: 0,\n          explanation: `The main skill for this lesson is to ${context.focus}.`\n        },\n        {\n          type: \"practice\",\n          style: \"Quick math\",\n          prompt: `During ${context.title}, a paper position has ${units} units of ${profile.asset} at $${unitPrice} each. What is its value before fees?`,\n          options: [`$${positionValue}`, `$${positionValue + unitPrice}`, `$${positionValue + (units * 3)}`, `$${Math.max(1, unitPrice - 2) * units}`],\n          answer: 0,\n          explanation: `Multiply ${units} units by $${unitPrice}: the position value is $${positionValue}.`\n        },\n        {\n          type: \"practice\",\n          style: \"Scenario\",\n          prompt: `Scenario for ${context.title}: ${context.scenario} What should happen next?`,\n          options: [context.move, `Follow the strongest recent price move right away.`, `Treat the first opinion as the final answer.`, `Wait for someone else to make the decision.`],\n          answer: 0,\n          explanation: `This lesson calls for the learner to ${context.move.toLowerCase()}`\n        },\n        {\n          type: \"practice\",\n          style: \"Reasoning\",\n          prompt: `Which mistake would most weaken a decision in ${context.title}?`,\n          options: [context.mistake, `Writing down the reason before acting.`, `Naming a risk that could change the plan.`, `Using a lesson idea in a paper trade.`],\n          answer: 0,\n          explanation: `The key mistake is: ${context.mistake}`\n        },\n        {\n          type: \"practice\",\n          style: \"Risk\",\n          prompt: `In ${context.title}, which risk is especially relevant to ${knowledge.term}?`,\n          options: [knowledge.risk, `The learner may forget the exact module number.`, `The task could take longer than a quick scroll.`, `The app may show more than one market category.`],\n          answer: 0,\n          explanation: `The important risk here is: ${knowledge.risk}.`\n        },\n        {\n          type: \"practice\",\n          style: \"Journal\",\n          prompt: `Which note best belongs in a ${context.title} journal entry?`,\n          options: [context.journal, `Only the final price, with no original reason.`, `A new explanation written after seeing the result.`, `The asset name with no note about the decision.`],\n          answer: 0,\n          explanation: `A useful entry for this lesson is: ${context.journal}`\n        },\n        {\n          type: \"practice\",\n          style: \"Source\",\n          prompt: `Which source warning matters most in ${context.title}?`,\n          options: [context.source, `A post includes the asset name in its headline.`, `A post has a short introduction before the claim.`, `A post uses a chart that is one day old.`],\n          answer: 0,\n          explanation: `The warning to notice is: ${context.source}`\n        },\n        {\n          type: \"practice\",\n          style: \"Application\",\n          prompt: `Which action shows that a learner used the ${context.title} lesson?`,\n          options: [context.move, `Follow a popular opinion without a written reason.`, `Ignore the lesson once a price starts moving.`, `Replace the plan with the latest headline.`],\n          answer: 0,\n          explanation: `Using this lesson means to ${context.move.toLowerCase()}`\n        }\n      ];\n    }\n\n    function buildLessonPages(number, title, shortName, focus, lessonNumber = 1, lessonTitle = \"Core ideas\") {\n      const lecturePage = {\n        type: \"text\",\n        title: `${lessonTitle}: ${title}`,\n        body: lessonTextForPage(lessonNumber - 1, title, shortName, focus)\n      };\n      const practicePages = buildPracticePages(number, title, shortName, focus, lessonNumber, lessonTitle);\n      const scrambledPracticePages = practicePages.map((page, index) => scrambleQuestion(page, `practice-${number}-${lessonNumber}-${index}`));\n      return [lecturePage, ...scrambledPracticePages];\n    }\n\n    function lessonTextForPage(index, title, shortName, focus) {\n      const pages = [\n        `This lesson is about ${focus}. A good learner does not just memorize a word; they connect the word to a decision. Example: if ${shortName} is moving up, the important question is not only \"Did it rise?\" but \"Why did it rise, and does that reason matter?\" Mini question: what new fact would make you more careful before a paper trade?`,\n        `${title} choices can look simple, but price moves usually have layers. Example: a stock can rise because sales improved, because investors are excited, or because the whole market moved. Those reasons are not equal. Mini question: which reason sounds strongest: better business results, social-media hype, or a random one-day jump?`,\n        `Before any paper trade, write a short thesis: \"I am watching this because...\" Then write the risk: \"I could be wrong if...\" Example: \"I am watching an ETF because it spreads risk across many companies. I could be wrong if the whole sector falls.\" Mini question: can you name both a reason and a risk?`,\n        `${shortName} practice works best when you compare choices. Example: one asset may have slower growth but steadier behavior, while another may move faster but be harder to predict. A stronger learner explains the tradeoff instead of only picking the exciting one. Mini question: what would you give up to choose the riskier asset?`,\n        `If a paper trade goes against you, the lesson is not over. Example: if your plan said \"this may drop if news is bad\" and bad news arrives, the drop may actually match your risk note. That is different from being surprised by a risk you never considered. Mini question: did the result break your thesis or confirm a known risk?`,\n        `A strong journal note includes the asset, reason, risk, result, and update. Example: \"I chose QQQ for tech exposure. Risk: tech stocks can fall together. Result: down 3%. Update: the whole Nasdaq was weak, so this was market risk, not just one company.\" Mini question: which part of that note helps you learn most?`,\n        `Different markets move for different reasons. Crypto may react to sentiment and regulation, indexes may react to broad economic news, and individual companies may react to earnings or product news. Mini question: if every stock in an index falls together, is that more likely company-specific risk or broad market risk?`,\n        `The safest learning habit is to slow down at the moment you feel most certain. Example: if everyone is excited about a name, that excitement can be information, but it can also be a warning sign. Mini question: what would you check before trusting a popular idea?`,\n        `Watch-only assets can still teach you. Example: a private company may be famous, but if it is not available for normal public trading, you can still study its business, competitors, and news without pressing Buy. Mini question: what can you learn from a company even when you cannot buy it?`,\n        `Portfolio thinking means asking how one choice fits with the rest of your plan. Example: adding another risky asset to a risky portfolio may not add much balance. Adding a steadier index fund might change the risk more. Mini question: does this choice add something new, or more of the same?`,\n        `Good investors are not always right. They are careful about being wrong. Example: a learner can say, \"If this drops below my risk line, I will review the thesis instead of pretending nothing changed.\" Mini question: what rule would help you review instead of panic?`,\n        `The best score is not just XP. It is being able to explain a choice clearly in your own words. Example: \"I picked this because of diversification, but I know the whole sector could fall.\" That is stronger than \"I picked it because it was green.\" Mini question: can your explanation survive a follow-up question?`\n      ];\n      return pages[index % pages.length];\n    }\n\n    function buildMultipleChoiceQuestions(number, title, shortName, focus, count) {\n      const profile = moduleProfile(number, title, shortName, focus);\n      const knowledge = moduleKnowledge(number);\n      const units = 3 + (number % 3);\n      const unitPrice = 8 + (number * 4);\n      const positionValue = units * unitPrice;\n      const questions = [\n        {\n          prompt: `Which sentence best defines ${knowledge.term}?`,\n          correct: knowledge.definition,\n          near: [`A name for every asset with a strong chart.`, `A reward for making a profitable practice trade.`, `A rule that removes uncertainty from an investment.`]\n        },\n        {\n          prompt: `A paper position has ${units} units at $${unitPrice} each. What is the position value before fees?`,\n          correct: `$${positionValue}`,\n          near: [`$${positionValue + unitPrice}`, `$${positionValue - unitPrice}`, `$${unitPrice + units}`]\n        },\n        {\n          prompt: `Which situation is the clearest example of ${knowledge.term}?`,\n          correct: knowledge.example,\n          near: [`A learner follows a headline without reading the details.`, `A learner picks the most familiar name in a list.`, `A learner assumes one outcome will happen every time.`]\n        },\n        {\n          prompt: `Which statement about ${knowledge.term} is false?`,\n          correct: knowledge.falseIdea,\n          near: [`The topic can involve a reason and a possible downside.`, `The topic can be used in a paper-trade plan.`, `The topic can matter even when a price is moving up.`]\n        },\n        {\n          prompt: `Which risk belongs most closely to ${knowledge.term}?`,\n          correct: knowledge.risk,\n          near: [`The module title may be hard to remember later.`, `The chart may use a different line color tomorrow.`, `The learner may have more than one unlocked lesson.`]\n        },\n        {\n          prompt: `Which action best applies ${knowledge.term} before practicing ${profile.asset}?`,\n          correct: knowledge.action,\n          near: [`Treat the asset name as the entire reason to act.`, `Wait for popularity to choose the next step.`, `Skip the plan because the trade is only simulated.`]\n        },\n        {\n          prompt: `Which result would be most relevant to the ${title} lesson?`,\n          correct: `A learner can state what ${knowledge.term} means and apply it to a new case.`,\n          near: [`A learner can name the asset with the fastest chart today.`, `A learner can finish without writing down any reason.`, `A learner can repeat a popular opinion from memory.`]\n        },\n        {\n          prompt: `A post claims, \"${knowledge.falseIdea}.\" What makes that claim unreliable?`,\n          correct: `It skips the conditions and risks that the lesson says still matter.`,\n          near: [`It uses too many words for a short market note.`, `It may be true only when every asset is green.`, `It is fine after the learner completes one quiz.`]\n        },\n        {\n          prompt: `A paper trade using ${profile.asset} finishes with a gain. What is the most useful journal entry?`,\n          correct: `The original reason, the result, and whether the expected risk appeared.`,\n          near: [`Only the gain, because a winning result explains itself.`, `A new reason invented after seeing the gain.`, `The asset name with no note about the decision.`]\n        },\n        {\n          prompt: `Which sentence best connects ${focus} to a real decision?`,\n          correct: `Use the lesson idea to set a reason, a limit, and a next step.`,\n          near: [`Use the lesson idea only after a trade is already finished.`, `Use the lesson idea to follow the loudest online opinion.`, `Use the lesson idea to ignore a result that feels inconvenient.`]\n        }\n      ];\n      return questions.slice(0, count).map((question, index) => {\n        const id = `m${number}-mc-${index + 1}`;\n        return scrambleQuestion({\n          id,\n          type: \"mc\",\n          prompt: question.prompt,\n          options: [\n            question.correct,\n            ...question.near\n          ],\n          answer: 0\n        }, id);\n      });\n    }\n\n    function buildSimulationQuestions(number, title, shortName, focus, count) {\n      const profile = moduleProfile(number, title, shortName, focus);\n      const knowledge = moduleKnowledge(number);\n      const units = 2 + (number % 4);\n      const unitPrice = 10 + (number * 2);\n      const positionValue = units * unitPrice;\n      const simulations = [\n        {\n          prompt: `Simulation: ${knowledge.example}. What is the best first response?`,\n          correct: knowledge.action,\n          near: [`Act immediately because the event already tells the whole story.`, `Ignore the event until the price returns to its old level.`, `Choose the asset that has the most comments online.`]\n        },\n        {\n          prompt: `Simulation: You buy ${units} paper units of ${profile.asset} at $${unitPrice} each. What amount is used for the buy?`,\n          correct: `$${positionValue}`,\n          near: [`$${positionValue + unitPrice}`, `$${unitPrice}`, `$${units}`]\n        },\n        {\n          prompt: `Simulation: A friend says, \"${knowledge.falseIdea}.\" What is the strongest reply?`,\n          correct: `That skips the conditions and risks that still affect the decision.`,\n          near: [`That is enough evidence when the chart is currently green.`, `That becomes true after a profitable paper trade.`, `That matters only when the asset is unfamiliar.`]\n        },\n        {\n          prompt: `Simulation: Your ${profile.asset} paper trade is gaining value, but ${knowledge.risk}. What should happen next?`,\n          correct: `Keep the stated limit and record whether the original reason still applies.`,\n          near: [`Remove the limit because the gain proves the risk is gone.`, `Add more units immediately so the gain becomes larger.`, `Delete the original note because the result is positive.`]\n        },\n        {\n          prompt: `Simulation: The result surprises you after studying ${title}. What should go in the next journal note?`,\n          correct: `The original reason, the actual result, and a clear update for the next step.`,\n          near: [`A new story that makes the original choice look perfect.`, `Only the final price, because the reason is no longer useful.`, `Nothing until the same surprise happens again.`]\n        }\n      ];\n      return simulations.slice(0, count).map((simulation, index) => {\n        const id = `m${number}-sim-${index + 1}`;\n        return scrambleQuestion({\n          id,\n          type: \"sim\",\n          prompt: simulation.prompt,\n          options: [\n            simulation.correct,\n            ...simulation.near\n          ],\n          answer: 0\n        }, id);\n      });\n    }\n\n    function buildCourseItems() {\n      const items = [];\n      courseModules.forEach((module, index) => {\n        items.push(module);\n        if ((index + 1) % 3 === 0) items.push(buildBigTest((index + 1) / 3, index - 2, index + 1));\n      });\n      items.push({\n        id: \"finish-course\",\n        kind: \"course\",\n        title: \"Finish Course\",\n        xp: 300,\n        body: \"You finished all 12 modules and every big test. Collect the course bonus.\"\n      });\n      return items;\n    }\n\n    function buildBigTest(testNumber, startModuleIndex, endModuleIndex) {\n      const modules = courseModules.slice(startModuleIndex, endModuleIndex);\n      const questions = [];\n      for (let i = 0; i < 21; i += 1) {\n        const module = modules[i % modules.length];\n        const profile = moduleProfile(module.number, module.shortTitle, module.shortTitle.toLowerCase(), module.focus);\n        const knowledge = moduleKnowledge(module.number);\n        const id = `big-${testNumber}-mc-${i + 1}`;\n        const units = 2 + (i % 4);\n        const unitPrice = 9 + (module.number * 3);\n        const positionValue = units * unitPrice;\n        const variants = [\n          {\n            prompt: `Big Test ${testNumber}: What does \"${knowledge.term}\" mean?`,\n            correct: knowledge.definition,\n            near: [`A guarantee that an asset will rise after a lesson.`, `A name for any popular market headline.`, `A shortcut that removes the need for a plan.`]\n          },\n          {\n            prompt: `Big Test ${testNumber}: ${units} paper units of ${profile.asset} cost $${unitPrice} each. What is the total cost?`,\n            correct: `$${positionValue}`,\n            near: [`$${positionValue + unitPrice}`, `$${positionValue - unitPrice}`, `$${unitPrice + units}`]\n          },\n          {\n            prompt: `Big Test ${testNumber}: Which risk belongs most closely to ${knowledge.term}?`,\n            correct: knowledge.risk,\n            near: [`The lesson card may have a short title.`, `The user may need to scroll to another panel.`, `A chart may have more than one visible range.`]\n          },\n          {\n            prompt: `Big Test ${testNumber}: Which statement about ${knowledge.term} is false?`,\n            correct: knowledge.falseIdea,\n            near: [`The concept can guide a paper-trade decision.`, `The concept can include a possible downside.`, `The concept can be written in a short journal note.`]\n          },\n          {\n            prompt: `Big Test ${testNumber}: Which action applies ${knowledge.term} most directly?`,\n            correct: knowledge.action,\n            near: [`Follow the first popular claim without a reason.`, `Use the asset name as the complete plan.`, `Ignore the lesson after the first price move.`]\n          }\n        ];\n        const variant = variants[i % variants.length];\n        questions.push(scrambleQuestion({\n          id,\n          type: \"mc\",\n          prompt: variant.prompt,\n          options: [\n            variant.correct,\n            ...variant.near\n          ],\n          answer: 0\n        }, id));\n      }\n      for (let i = 0; i < 9; i += 1) {\n        const module = modules[i % modules.length];\n        const profile = moduleProfile(module.number, module.shortTitle, module.shortTitle.toLowerCase(), module.focus);\n        const knowledge = moduleKnowledge(module.number);\n        const id = `big-${testNumber}-sim-${i + 1}`;\n        const variants = [\n          {\n            prompt: `Simulation ${i + 1}: ${knowledge.example}. What is the best first move?`,\n            correct: knowledge.action,\n            near: [`Act immediately because the event already explains everything.`, `Ignore the event until the chart returns to its old price.`, `Choose the asset with the loudest online discussion.`]\n          },\n          {\n            prompt: `Simulation ${i + 1}: ${profile.asset} is moving up, but ${knowledge.risk}. What should the learner do?`,\n            correct: `Keep the stated limit and record whether the original reason still applies.`,\n            near: [`Remove the limit because the move is positive.`, `Add the largest possible position immediately.`, `Delete the risk note because it feels pessimistic.`]\n          },\n          {\n            prompt: `Simulation ${i + 1}: A friend says, \"${knowledge.falseIdea}.\" What is the best response?`,\n            correct: `That skips the real conditions and risks behind the topic.`,\n            near: [`That is enough proof when the price is rising.`, `That becomes correct after a winning trade.`, `That matters only for unfamiliar assets.`]\n          },\n          {\n            prompt: `Simulation ${i + 1}: A paper trade ends differently from expected. What should be written down?`,\n            correct: `The original reason, the result, and a clear update for the next step.`,\n            near: [`Only the final price, because the plan is now irrelevant.`, `A new reason that makes the outcome look obvious.`, `Nothing until the same result happens again.`]\n          }\n        ];\n        const variant = variants[i % variants.length];\n        questions.push(scrambleQuestion({\n          id,\n          type: \"sim\",\n          prompt: variant.prompt,\n          options: [\n            variant.correct,\n            ...variant.near\n          ],\n          answer: 0\n        }, id));\n      }\n      return {\n        id: `big-test-${testNumber}`,\n        kind: \"bigTest\",\n        title: `Big Test ${testNumber}`,\n        xp: 150,\n        perfectXp: 50,\n        questions\n      };\n    }\n\n    const streakRewards = [\n      [7, 80],\n      [28, 255],\n      [60, 430],\n      [120, 700],\n      [200, 950],\n      [300, 1150]\n    ];\n\n    const TASK_VERSION = \"three-task-streak-board-v1\";\n    const taskBank = {\n      Bronze: [\n        { id: \"lesson-one\", metric: \"lessons\", amount: 1, rank: 1, text: \"Complete 1 lesson in the learning course.\" },\n        { id: \"lesson-two\", metric: \"lessons\", amount: 2, rank: 2, text: \"Complete 2 lessons in the learning course.\" },\n        { id: \"lesson-three\", metric: \"lessons\", amount: 3, rank: 3, text: \"Complete 3 lessons in the learning course.\" },\n        { id: \"lesson-four\", metric: \"lessons\", amount: 4, rank: 4, text: \"Complete 4 lessons in the learning course.\" }\n      ],\n      Silver: [\n        { id: \"lesson-two\", metric: \"lessons\", amount: 2, rank: 1, text: \"Complete 2 lessons, including every practice question.\" },\n        { id: \"lesson-three\", metric: \"lessons\", amount: 3, rank: 2, text: \"Complete 3 lessons, including every practice question.\" },\n        { id: \"lesson-five\", metric: \"lessons\", amount: 5, rank: 3, text: \"Complete 5 lessons in the learning course.\" },\n        { id: \"perfect-quiz\", metric: \"perfectQuizzes\", amount: 1, rank: 4, text: \"Earn 100% on 1 module quiz.\" }\n      ],\n      Gold: [\n        { id: \"lesson-three\", metric: \"lessons\", amount: 3, rank: 1, text: \"Complete 3 lessons in the learning course.\" },\n        { id: \"lesson-four\", metric: \"lessons\", amount: 4, rank: 2, text: \"Complete 4 lessons in the learning course.\" },\n        { id: \"module-quiz\", metric: \"quizzes\", amount: 1, rank: 3, text: \"Complete 1 module quiz.\" },\n        { id: \"final-test\", metric: \"finalTests\", amount: 1, rank: 4, text: \"Complete 1 final test.\" }\n      ]\n    };\n    const taskProfiles = {\n      returning: { id: \"returning\", rank: 1, guide: \"Welcome back. Your three daily goals are in the easier restart range.\" },\n      starter: { id: \"starter\", rank: 1, guide: \"Starter range: complete one Bronze, one Silver, and one Gold goal.\" },\n      building: { id: \"building\", rank: 2, guide: \"Building range: today's three goals need more course progress.\" },\n      advanced: { id: \"advanced\", rank: 3, guide: \"Advanced range: today's goals include a module quiz challenge.\" },\n      mastery: { id: \"mastery\", rank: 4, guide: \"Mastery range: today's Gold goal is a final test challenge.\" }\n    };\n\n    const taskXp = { Bronze: 35, Silver: 60, Gold: 110 };\n    const chartRanges = {\n      \"1D\": { range: \"1d\", interval: \"1m\", title: \"1 day\" },\n      \"1W\": { range: \"5d\", interval: \"15m\", title: \"1 week\" },\n      \"1M\": { range: \"1mo\", interval: \"1d\", title: \"1 month\" },\n      \"1Y\": { range: \"1y\", interval: \"1d\", title: \"1 year\" },\n      \"5Y\": { range: \"5y\", interval: \"1wk\", title: \"5 years\" },\n      \"YTD\": { range: \"ytd\", interval: \"1d\", title: \"year to date\" },\n      \"ALL\": { range: \"max\", interval: \"1mo\", title: \"all time\" }\n    };\n    const chartPlot = { width: 640, height: 260, left: 92, right: 24, top: 24, bottom: 34 };\n    const MARKET_CHART_CACHE_KEY = \"invest-quest-market-chart-cache-v1\";\n    const MARKET_CHART_CACHE_LIMIT = 12;\n    const marketChartCacheMaxAge = {\n      \"1D\": 5 * 60 * 1000,\n      \"1W\": 30 * 60 * 1000,\n      \"1M\": 2 * 60 * 60 * 1000,\n      \"1Y\": 6 * 60 * 60 * 1000,\n      \"5Y\": 12 * 60 * 60 * 1000,\n      \"YTD\": 6 * 60 * 60 * 1000,\n      \"ALL\": 12 * 60 * 60 * 1000\n    };\n    const COURSE_VERSION = \"ten-lessons-eight-questions-v1\";\n    const SKIP_QUESTION_COUNT = 30;\n    const SKIP_MISS_LIMIT = 3;\n    const SKIP_TIME_LIMIT_MS = 5 * 60 * 1000;\n    const SKIP_REWARD_XP = 300;\n    const state = loadState();\n    let currentStep = 0;\n    let marketChartState = { asset: null, data: null, loading: false, error: \"\", rangeKey: \"1D\" };\n    let marketChartTimer = 0;\n    let marketChartRequest = 0;\n    let tradeState = null;\n    let skipChallengeTimer = 0;\n    let courseOverviewMode = false;\n\n    function defaultState() {\n      return {\n        onboarded: false,\n        profile: { reason: \"\", age: \"\", first: \"\", last: \"\", level: \"Beginner\" },\n        xp: 0,\n        streak: 0,\n        courseVersion: COURSE_VERSION,\n        claimed: {},\n        portfolio: { holdings: {} },\n        taskDay: \"\",\n        taskLastSeenDay: \"\",\n        taskStreak: 0,\n        taskProfile: \"\",\n        taskVersion: TASK_VERSION,\n        completed: {},\n        courseProgress: {},\n        activeCourseId: \"\",\n        tasks: []\n      };\n    }\n\n    function loadState() {\n      try {\n        const saved = JSON.parse(localStorage.getItem(\"investQuestState\") || \"{}\");\n        const base = defaultState();\n        const merged = {\n          ...base,\n          ...saved,\n          profile: { ...base.profile, ...(saved.profile || {}) },\n          claimed: { ...base.claimed, ...(saved.claimed || {}) },\n          portfolio: {\n            ...base.portfolio,\n            ...(saved.portfolio || {}),\n            holdings: { ...base.portfolio.holdings, ...((saved.portfolio || {}).holdings || {}) }\n          },\n          completed: { ...base.completed, ...(saved.completed || {}) },\n          courseProgress: { ...base.courseProgress, ...(saved.courseProgress || {}) }\n        };\n        if (saved.courseVersion !== COURSE_VERSION) {\n          merged.courseVersion = COURSE_VERSION;\n          merged.completed = {};\n          merged.courseProgress = {};\n          merged.activeCourseId = \"\";\n        }\n        return merged;\n      } catch {\n        return defaultState();\n      }\n    }\n\n    function saveState() {\n      localStorage.setItem(\"investQuestState\", JSON.stringify(state));\n    }\n\n    function showToast(message) {\n      const toast = document.getElementById(\"toast\");\n      toast.textContent = message;\n      toast.classList.add(\"show\");\n      window.clearTimeout(showToast.timer);\n      showToast.timer = window.setTimeout(() => toast.classList.remove(\"show\"), 2300);\n    }\n\n    function addXp(amount, label) {\n      const before = state.xp;\n      state.xp = Math.max(0, state.xp + amount);\n      const applied = state.xp - before;\n      saveState();\n      renderStats();\n      showToast(`${applied > 0 ? \"+\" : \"\"}${applied} XP ${label ? \"for \" + label : \"\"}`);\n    }\n\n    function findMarketAsset(name, symbol) {\n      for (const group of markets) {\n        for (const item of group.items) {\n          const [assetName, status, note, ticker] = item;\n          if (assetName === name && ticker === symbol) {\n            return { name: assetName, status, note, symbol: ticker, category: group.category };\n          }\n        }\n      }\n      return null;\n    }\n\n    function openMarketChart(asset) {\n      if (!asset || !asset.symbol) return;\n      window.clearTimeout(marketChartTimer);\n      const rangeKey = marketChartState.rangeKey || \"1D\";\n      const cachedData = readMarketChartCache(asset.symbol, rangeKey);\n      marketChartState = { asset, data: cachedData, loading: true, error: \"\", rangeKey };\n      renderMarketChart();\n      fetchMarketChart(asset);\n    }\n\n    function setMarketChartRange(rangeKey) {\n      if (!chartRanges[rangeKey]) return;\n      marketChartState.rangeKey = rangeKey;\n      marketChartState.data = marketChartState.asset\n        ? readMarketChartCache(marketChartState.asset.symbol, rangeKey)\n        : null;\n      if (marketChartState.asset) fetchMarketChart(marketChartState.asset);\n      else renderMarketChart();\n    }\n\n    async function fetchMarketChart(asset = marketChartState.asset) {\n      if (!asset || !asset.symbol) return;\n      const requestId = ++marketChartRequest;\n      marketChartState.loading = true;\n      marketChartState.error = \"\";\n      renderMarketChart();\n      const rangeKey = marketChartState.rangeKey;\n      const rangeConfig = chartRanges[rangeKey] || chartRanges[\"1D\"];\n      const urls = yahooChartApiUrls(asset.symbol, rangeConfig);\n      try {\n        const payload = await fetchYahooChartPayload(urls);\n        if (requestId !== marketChartRequest) return;\n        marketChartState.data = marketChartDataFromPayload(payload, rangeKey, rangeConfig);\n        writeMarketChartCache(asset.symbol, rangeKey, marketChartState.data);\n      } catch (error) {\n        if (requestId !== marketChartRequest) return;\n        marketChartState.error = marketChartState.data\n          ? \"Showing a recent chart while live prices reconnect.\"\n          : \"Chart did not load. Check your connection, then refresh the chart.\";\n      } finally {\n        if (requestId !== marketChartRequest) return;\n        marketChartState.loading = false;\n        renderMarketChart();\n        scheduleMarketChartRefresh();\n      }\n    }\n\n    function marketChartDataFromPayload(payload, rangeKey, rangeConfig) {\n      const result = payload.chart && payload.chart.result && payload.chart.result[0];\n      const quote = result && result.indicators && result.indicators.quote && result.indicators.quote[0];\n      if (!result || !quote || !Array.isArray(result.timestamp)) throw new Error(\"Missing chart data\");\n      const closes = quote.close || [];\n      const points = result.timestamp.map((time, index) => {\n        const close = closes[index];\n        return {\n          time: time * 1000,\n          close: typeof close === \"number\" ? close : NaN\n        };\n      }).filter(point => Number.isFinite(point.close) && point.close > 0);\n      if (points.length < 2) throw new Error(\"Not enough chart data\");\n      const meta = result.meta || {};\n      const lastPoint = points[points.length - 1];\n      const price = Number.isFinite(Number(meta.regularMarketPrice)) ? Number(meta.regularMarketPrice) : lastPoint.close;\n      const previousClose = Number.isFinite(Number(meta.previousClose)) ? Number(meta.previousClose) : points[0].close;\n      const previous = rangeKey === \"1D\" ? previousClose : points[0].close;\n      return {\n        points,\n        price,\n        previous,\n        currency: meta.currency || \"\",\n        exchange: meta.exchangeName || meta.fullExchangeName || \"\",\n        quoteType: meta.quoteType || \"\",\n        longName: meta.longName || meta.shortName || \"\",\n        dayHigh: positiveMetaNumber(meta.regularMarketDayHigh),\n        dayLow: positiveMetaNumber(meta.regularMarketDayLow),\n        volume: positiveMetaNumber(meta.regularMarketVolume),\n        marketCap: positiveMetaNumber(meta.marketCap),\n        fiftyTwoWeekHigh: positiveMetaNumber(meta.fiftyTwoWeekHigh),\n        fiftyTwoWeekLow: positiveMetaNumber(meta.fiftyTwoWeekLow),\n        rangeTitle: rangeConfig.title,\n        updatedAt: Date.now()\n      };\n    }\n\n    function positiveMetaNumber(value) {\n      const number = Number(value);\n      return Number.isFinite(number) && number > 0 ? number : NaN;\n    }\n\n    function validMarketChartData(data) {\n      return Boolean(\n        data &&\n        Array.isArray(data.points) &&\n        data.points.length >= 2 &&\n        Number.isFinite(Number(data.price)) &&\n        Number(data.price) > 0 &&\n        Number.isFinite(Number(data.previous)) &&\n        Number(data.previous) > 0 &&\n        data.points.every(point =>\n          Number.isFinite(Number(point.time)) &&\n          Number.isFinite(Number(point.close)) &&\n          Number(point.close) > 0\n        )\n      );\n    }\n\n    function marketChartCacheId(symbol, rangeKey) {\n      return `${String(symbol).toUpperCase()}|${rangeKey}`;\n    }\n\n    function readMarketChartCache(symbol, rangeKey) {\n      try {\n        const cache = JSON.parse(localStorage.getItem(MARKET_CHART_CACHE_KEY) || \"{}\");\n        const entry = cache[marketChartCacheId(symbol, rangeKey)];\n        const maxAge = marketChartCacheMaxAge[rangeKey] || marketChartCacheMaxAge[\"1D\"];\n        if (!entry || Date.now() - Number(entry.savedAt) > maxAge || !validMarketChartData(entry.data)) {\n          return null;\n        }\n        return entry.data;\n      } catch (error) {\n        return null;\n      }\n    }\n\n    function writeMarketChartCache(symbol, rangeKey, data) {\n      if (!validMarketChartData(data)) return;\n      try {\n        const cache = JSON.parse(localStorage.getItem(MARKET_CHART_CACHE_KEY) || \"{}\");\n        cache[marketChartCacheId(symbol, rangeKey)] = { savedAt: Date.now(), data };\n        const trimmed = Object.fromEntries(\n          Object.entries(cache)\n            .sort((left, right) => Number(right[1].savedAt) - Number(left[1].savedAt))\n            .slice(0, MARKET_CHART_CACHE_LIMIT)\n        );\n        localStorage.setItem(MARKET_CHART_CACHE_KEY, JSON.stringify(trimmed));\n      } catch (error) {\n        // A full or unavailable browser cache should never block live chart loading.\n      }\n    }\n\n    function scheduleMarketChartRefresh() {\n      window.clearTimeout(marketChartTimer);\n      if (marketChartState.asset) {\n        marketChartTimer = window.setTimeout(() => fetchMarketChart(marketChartState.asset), 30000);\n      }\n    }\n\n    function renderMarketChart() {\n      const panel = document.getElementById(\"marketChart\");\n      if (!panel) return;\n      const { asset, data, loading, error } = marketChartState;\n      if (!asset) {\n        panel.innerHTML = `\n          <div class=\"market-chart-head\">\n            <div>\n              <h3>Yahoo Finance chart</h3>\n              <p class=\"muted\">Pick a row below or enter a Yahoo symbol to load its graph.</p>\n            </div>\n          </div>\n          ${marketRangeButtons()}\n          <div class=\"chart-empty\">No chart selected yet.</div>\n          ${symbolSearchTemplate()}\n        `;\n        wireMarketChartControls();\n        return;\n      }\n\n      const change = data ? data.price - data.previous : 0;\n      const percent = data && data.previous ? (change / data.previous) * 100 : 0;\n      const direction = change >= 0 ? \"up\" : \"down\";\n      const priceLabel = data ? formatMarketPrice(data.price, data.currency) : \"...\";\n      const changeDigits = data && Math.abs(data.price) < 2 ? 6 : 2;\n      const changeLabel = data ? `${change >= 0 ? \"+\" : \"\"}${change.toFixed(changeDigits)} (${percent >= 0 ? \"+\" : \"\"}${percent.toFixed(2)}%)` : \"Loading\";\n      const updated = data ? new Date(data.updatedAt).toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\", second: \"2-digit\" }) : \"\";\n      panel.innerHTML = `\n        <div class=\"market-chart-head\">\n          <div>\n            <h3>${escapeHtml(asset.name)} <span class=\"muted\">${escapeHtml(asset.symbol)}</span></h3>\n            <p class=\"muted\">${escapeHtml(asset.note)}${data && data.exchange ? \" • \" + escapeHtml(data.exchange) : \"\"}${updated ? \" • updated \" + updated : \"\"}</p>\n          </div>\n          <div class=\"quote-price\">\n            <div>${priceLabel}</div>\n            <div class=\"quote-change ${direction}\">${changeLabel}</div>\n          </div>\n        </div>\n        ${marketRangeButtons()}\n        <div class=\"chart-box\">\n          ${data ? `${marketChartSvg(data.points, direction, data.currency)}<div class=\"chart-tooltip\" id=\"chartTooltip\"></div>` : `<div class=\"chart-empty\">${loading ? \"Loading Yahoo Finance chart...\" : \"Waiting for chart data.\"}</div>`}\n        </div>\n        ${data ? marketInfoTemplate(asset, data) : \"\"}\n        ${portfolioInfoTemplate(asset, data)}\n        ${error ? `<p class=\"muted\" style=\"margin-top:8px\">${error}</p>` : \"\"}\n        ${symbolSearchTemplate(asset.symbol)}\n        <div class=\"chart-actions\">\n          <button class=\"btn green\" data-chart-trade=\"buy\" type=\"button\">Buy</button>\n          <button class=\"btn secondary\" data-chart-trade=\"sell\" type=\"button\">Sell</button>\n          <a class=\"btn secondary\" href=\"${yahooQuoteUrl(asset.symbol)}\" target=\"_blank\" rel=\"noopener\">Open Yahoo</a>\n          <button class=\"btn secondary\" id=\"refreshChartBtn\">Refresh chart</button>\n        </div>\n      `;\n      wireMarketChartControls();\n      wireMarketChartHover();\n    }\n\n    function marketInfoTemplate(asset, data) {\n      const dayRange = Number.isFinite(data.dayLow) && Number.isFinite(data.dayHigh)\n        ? `${formatMarketPrice(data.dayLow, data.currency)} - ${formatMarketPrice(data.dayHigh, data.currency)}`\n        : \"Unavailable\";\n      const weekRange = Number.isFinite(data.fiftyTwoWeekLow) && Number.isFinite(data.fiftyTwoWeekHigh)\n        ? `${formatMarketPrice(data.fiftyTwoWeekLow, data.currency)} - ${formatMarketPrice(data.fiftyTwoWeekHigh, data.currency)}`\n        : \"Unavailable\";\n      const items = [\n        [\"Asset type\", data.quoteType || asset.note || \"Market asset\"],\n        [\"Exchange\", data.exchange || \"Unavailable\"],\n        [\"Previous close\", Number.isFinite(data.previous) ? formatMarketPrice(data.previous, data.currency) : \"Unavailable\"],\n        [\"Day range\", dayRange],\n        [\"Volume\", Number.isFinite(data.volume) ? formatCompactNumber(data.volume) : \"Unavailable\"],\n        [\"Market cap\", Number.isFinite(data.marketCap) ? formatCompactNumber(data.marketCap) : \"Unavailable\"],\n        [\"52-week range\", weekRange],\n        [\"Data source\", \"Yahoo Finance\"]\n      ];\n      return `\n        <section class=\"market-info\" aria-label=\"${escapeAttr(asset.name)} information\">\n          <h4>About this market</h4>\n          <div class=\"market-info-grid\">\n            ${items.map(([label, value]) => `\n              <div class=\"market-info-item\">\n                <span>${escapeHtml(label)}</span>\n                <strong>${escapeHtml(String(value))}</strong>\n              </div>\n            `).join(\"\")}\n          </div>\n        </section>\n      `;\n    }\n\n    function formatCompactNumber(value) {\n      const number = Number(value);\n      if (!Number.isFinite(number)) return \"Unavailable\";\n      return number.toLocaleString(undefined, { notation: \"compact\", maximumFractionDigits: 2 });\n    }\n\n    function portfolioInfoTemplate(asset, data) {\n      const holding = getPortfolioHolding(asset.symbol);\n      const price = data && Number.isFinite(Number(data.price)) ? Number(data.price) : getTradePrice(asset);\n      const positionValue = price > 0 ? holding.units * price : NaN;\n      const positionLabel = Number.isFinite(positionValue) ? formatSignedMoney(positionValue, data?.currency || \"USD\") : \"Unavailable\";\n      const netDollarsLabel = formatSignedMoney(holding.netDollars, \"USD\");\n      const unitsLabel = holding.units.toLocaleString(undefined, { maximumFractionDigits: 8 });\n      return `\n        <section class=\"market-info\" aria-label=\"Your ${escapeAttr(asset.name)} paper position\">\n          <h4>Your paper position</h4>\n          <div class=\"market-info-grid\">\n            <div class=\"market-info-item\"><span>Position value</span><strong>${escapeHtml(positionLabel)}</strong></div>\n            <div class=\"market-info-item\"><span>Units</span><strong>${escapeHtml(unitsLabel)}</strong></div>\n            <div class=\"market-info-item\"><span>Net trade dollars</span><strong>${escapeHtml(netDollarsLabel)}</strong></div>\n            <div class=\"market-info-item\"><span>Trade mode</span><strong>Paper only</strong></div>\n          </div>\n        </section>\n      `;\n    }\n\n    function formatSignedMoney(value, currency = \"USD\") {\n      const number = Number(value);\n      if (!Number.isFinite(number)) return \"Unavailable\";\n      const sign = number < 0 ? \"-\" : number > 0 ? \"+\" : \"\";\n      return `${sign}${formatMarketPrice(Math.abs(number), currency)}`;\n    }\n\n    function marketRangeButtons() {\n      return `\n        <div class=\"range-row\" aria-label=\"Chart time range\">\n          ${Object.keys(chartRanges).map(key => `\n            <button class=\"range-btn ${marketChartState.rangeKey === key ? \"active\" : \"\"}\" data-range=\"${key}\">${key}</button>\n          `).join(\"\")}\n        </div>\n      `;\n    }\n\n    function symbolSearchTemplate(value = \"\") {\n      return `\n        <form class=\"symbol-search\" id=\"symbolSearch\">\n          <input id=\"symbolInput\" type=\"text\" value=\"${escapeAttr(value)}\" placeholder=\"Yahoo symbol, example VOO or AAPL\" aria-label=\"Yahoo Finance symbol\">\n          <button class=\"btn green\" type=\"submit\">Show graph</button>\n        </form>\n      `;\n    }\n\n    function wireMarketChartControls() {\n      const panel = document.getElementById(\"marketChart\");\n      if (!panel) return;\n      panel.querySelectorAll(\"[data-range]\").forEach(button => {\n        button.addEventListener(\"click\", () => setMarketChartRange(button.dataset.range));\n      });\n      const refresh = panel.querySelector(\"#refreshChartBtn\");\n      if (refresh) refresh.addEventListener(\"click\", () => fetchMarketChart(marketChartState.asset));\n      panel.querySelectorAll(\"[data-chart-trade]\").forEach(button => {\n        button.addEventListener(\"click\", () => openTradePage(marketChartState.asset, button.dataset.chartTrade));\n      });\n      const search = panel.querySelector(\"#symbolSearch\");\n      if (search) {\n        search.addEventListener(\"submit\", event => {\n          event.preventDefault();\n          const input = panel.querySelector(\"#symbolInput\");\n          const symbol = input ? input.value.trim().toUpperCase() : \"\";\n          if (!symbol) {\n            showToast(\"Type a Yahoo symbol first.\");\n            return;\n          }\n          openMarketChart({ name: symbol, status: \"can\", note: \"Custom Yahoo symbol\", symbol });\n        });\n      }\n    }\n\n    function wireMarketChartHover() {\n      const data = marketChartState.data;\n      const chartBox = document.querySelector(\"#marketChart .chart-box\");\n      const svg = chartBox ? chartBox.querySelector(\"svg\") : null;\n      const tooltip = document.getElementById(\"chartTooltip\");\n      const hoverLine = document.getElementById(\"chartHoverLine\");\n      if (!data || !chartBox || !svg || !tooltip || !hoverLine || !data.points.length) return;\n\n      chartBox.addEventListener(\"mousemove\", event => {\n        const rect = chartBox.getBoundingClientRect();\n        const screenMatrix = svg.getScreenCTM();\n        if (!screenMatrix) return;\n        const cursorPoint = svg.createSVGPoint();\n        cursorPoint.x = event.clientX;\n        cursorPoint.y = event.clientY;\n        const svgX = cursorPoint.matrixTransform(screenMatrix.inverse()).x;\n        const lineInset = 8;\n        const lineLeft = chartPlot.left + lineInset;\n        const lineRight = chartPlot.width - chartPlot.right - lineInset;\n        const lineWidth = lineRight - lineLeft;\n        const clampedSvgX = Math.max(lineLeft, Math.min(lineRight, svgX));\n        const rawIndex = Math.round(((clampedSvgX - lineLeft) / lineWidth) * (data.points.length - 1));\n        const index = Math.max(0, Math.min(data.points.length - 1, rawIndex));\n        const point = data.points[index];\n        const pointX = lineLeft + (index / Math.max(data.points.length - 1, 1)) * lineWidth;\n        hoverLine.setAttribute(\"x1\", pointX.toFixed(1));\n        hoverLine.setAttribute(\"x2\", pointX.toFixed(1));\n        const graphPoint = svg.createSVGPoint();\n        graphPoint.x = pointX;\n        graphPoint.y = chartPlot.top;\n        const cssX = graphPoint.matrixTransform(screenMatrix).x - rect.left;\n        tooltip.innerHTML = `<strong>${formatHoverPrice(point.close, data.currency)}</strong>${formatHoverTime(point.time)}`;\n        const tooltipWidth = tooltip.offsetWidth || 150;\n        const gap = 12;\n        const minLeft = gap;\n        const maxLeft = rect.width - tooltipWidth - gap;\n        const preferredLeft = cssX + tooltipWidth + gap > rect.width ? cssX - tooltipWidth - gap : cssX + gap;\n        const tooltipLeft = Math.max(minLeft, Math.min(maxLeft, preferredLeft));\n        tooltip.style.left = `${tooltipLeft}px`;\n        chartBox.classList.add(\"hovering\");\n      });\n\n      chartBox.addEventListener(\"mouseleave\", () => {\n        chartBox.classList.remove(\"hovering\");\n      });\n    }\n\n    function marketChartSvg(points, direction, currency) {\n      const { width, height, left: plotLeft, right: plotRight, top: plotTop, bottom: plotBottom } = chartPlot;\n      const values = points.map(point => point.close);\n      const min = Math.min(...values);\n      const max = Math.max(...values);\n      if (!Number.isFinite(min) || !Number.isFinite(max) || min <= 0) {\n        return `<div class=\"chart-empty\">Price chart data is missing.</div>`;\n      }\n      const rawSpread = Math.max(max - min, Math.abs(max) * 0.001, 0.000000001);\n      const padding = rawSpread * 0.12;\n      const lowerPadding = Math.min(padding, min * 0.12);\n      const displayMin = min - lowerPadding;\n      const displayMax = max + padding;\n      const spread = displayMax - displayMin;\n      const color = direction === \"up\" ? \"#168a58\" : \"#c04444\";\n      const lineInset = 8;\n      const lineLeft = plotLeft + lineInset;\n      const lineRight = width - plotRight - lineInset;\n      const lineWidth = lineRight - lineLeft;\n      const coords = points.map((point, index) => {\n        const x = lineLeft + (index / Math.max(points.length - 1, 1)) * lineWidth;\n        const y = height - plotBottom - ((point.close - displayMin) / spread) * (height - plotTop - plotBottom);\n        return `${x.toFixed(1)},${y.toFixed(1)}`;\n      }).join(\" \");\n      const firstTime = formatChartEdgeTime(points[0].time);\n      const lastTime = formatChartEdgeTime(points[points.length - 1].time);\n      const ticks = [displayMax, displayMin + spread * 0.67, displayMin + spread * 0.33, displayMin];\n      return `\n        <svg viewBox=\"0 0 ${width} ${height}\" role=\"img\" aria-label=\"Intraday price chart\">\n          <defs>\n            <clipPath id=\"marketChartPlotClip\">\n              <rect x=\"${lineLeft}\" y=\"${plotTop}\" width=\"${lineWidth}\" height=\"${height - plotTop - plotBottom}\" />\n            </clipPath>\n          </defs>\n          <text x=\"${plotLeft - 10}\" y=\"18\" text-anchor=\"end\" fill=\"#596256\" font-size=\"12\" font-weight=\"850\">Price $</text>\n          <line x1=\"${plotLeft}\" y1=\"${plotTop}\" x2=\"${plotLeft}\" y2=\"${height - plotBottom}\" stroke=\"#dfe3dc\" />\n          ${ticks.map(value => {\n            const y = height - plotBottom - ((value - displayMin) / spread) * (height - plotTop - plotBottom);\n            return `\n              <line x1=\"${lineLeft}\" y1=\"${y.toFixed(1)}\" x2=\"${lineRight}\" y2=\"${y.toFixed(1)}\" stroke=\"#edf0ea\" />\n              <text x=\"${plotLeft - 10}\" y=\"${(y + 4).toFixed(1)}\" text-anchor=\"end\" fill=\"#596256\" font-size=\"12\" font-weight=\"850\">${formatAxisPrice(value, currency)}</text>\n            `;\n          }).join(\"\")}\n          <polyline points=\"${coords}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" clip-path=\"url(#marketChartPlotClip)\" />\n          <line class=\"chart-hover-line\" id=\"chartHoverLine\" x1=\"${lineLeft}\" y1=\"${plotTop}\" x2=\"${lineLeft}\" y2=\"${height - plotBottom}\" clip-path=\"url(#marketChartPlotClip)\" aria-hidden=\"true\" />\n          <text x=\"${lineLeft}\" y=\"${height - 9}\" fill=\"#778075\" font-size=\"13\" font-weight=\"800\">${firstTime}</text>\n          <text x=\"${lineRight}\" y=\"${height - 9}\" text-anchor=\"end\" fill=\"#778075\" font-size=\"13\" font-weight=\"800\">${lastTime}</text>\n        </svg>\n      `;\n    }\n\n    function formatMarketPrice(price, currency) {\n      const value = Number(price);\n      const options = Math.abs(value) < 2\n        ? { minimumFractionDigits: 6, maximumFractionDigits: 6 }\n        : { maximumFractionDigits: value < 10 ? 4 : 2 };\n      return `${currency ? currency + \" \" : \"\"}${value.toLocaleString(undefined, options)}`;\n    }\n\n    function formatAxisPrice(price, currency) {\n      const value = Number(price);\n      const digits = Math.abs(value) < 2 ? 6 : Math.abs(value) < 10 ? 2 : Math.abs(value) < 100 ? 1 : 0;\n      const label = value.toLocaleString(undefined, {\n        minimumFractionDigits: Math.abs(value) < 2 ? 6 : 0,\n        maximumFractionDigits: digits\n      });\n      return currency === \"USD\" || !currency ? `$${label}` : `${currency} ${label}`;\n    }\n\n    function formatHoverPrice(price, currency) {\n      const value = Number(price);\n      const label = value.toLocaleString(undefined, {\n        minimumFractionDigits: Math.abs(value) < 2 ? 6 : value < 100 ? 2 : 0,\n        maximumFractionDigits: Math.abs(value) < 2 ? 6 : 2\n      });\n      return currency === \"USD\" || !currency ? `$${label}` : `${currency} ${label}`;\n    }\n\n    function formatHoverTime(time) {\n      const date = new Date(time);\n      const rangeKey = marketChartState.rangeKey;\n      if (rangeKey === \"1D\") {\n        return date.toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\" });\n      }\n      return date.toLocaleString([], { month: \"short\", day: \"numeric\", year: \"numeric\", hour: \"numeric\", minute: \"2-digit\" });\n    }\n\n    function formatChartEdgeTime(time) {\n      const date = new Date(time);\n      const rangeKey = marketChartState.rangeKey;\n      if (rangeKey === \"1D\") {\n        return date.toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\" });\n      }\n      if (rangeKey === \"ALL\") {\n        return date.toLocaleDateString([], { month: \"short\", year: \"numeric\" });\n      }\n      return date.toLocaleDateString([], { month: \"short\", day: \"numeric\", year: \"numeric\" });\n    }\n\n    function yahooQuoteUrl(symbol) {\n      return `https://finance.yahoo.com/quote/${encodeURIComponent(symbol)}`;\n    }\n\n    async function fetchYahooChartPayload(urls) {\n      const controllers = urls.map(() => new AbortController());\n      try {\n        return await Promise.any(urls.map(async (url, index) => {\n          const controller = controllers[index];\n          const timeout = window.setTimeout(() => controller.abort(), 10000);\n          try {\n            const response = await fetch(url, { cache: \"no-store\", signal: controller.signal });\n            if (!response.ok) throw new Error(\"Yahoo request failed\");\n            let payload = await response.json();\n            if (payload && typeof payload.contents === \"string\") {\n              payload = JSON.parse(payload.contents);\n            }\n            const result = payload.chart && payload.chart.result && payload.chart.result[0];\n            const quote = result && result.indicators && result.indicators.quote && result.indicators.quote[0];\n            const closes = quote && Array.isArray(quote.close) ? quote.close : [];\n            const positiveCloses = closes.filter(value => typeof value === \"number\" && Number.isFinite(value) && value > 0);\n            if (!result || !Array.isArray(result.timestamp) || positiveCloses.length < 2) {\n              throw new Error(\"Invalid chart data\");\n            }\n            return payload;\n          } finally {\n            window.clearTimeout(timeout);\n          }\n        }));\n      } finally {\n        controllers.forEach(controller => controller.abort());\n      }\n    }\n\n    function yahooChartApiUrls(symbol, rangeConfig) {\n      const params = new URLSearchParams({\n        symbol,\n        range: rangeConfig.range,\n        interval: rangeConfig.interval,\n        includePrePost: \"true\",\n        _: String(Date.now())\n      });\n      const isGitHubPages = location.hostname.endsWith(\".github.io\");\n      if ((location.protocol === \"http:\" || location.protocol === \"https:\") && !isGitHubPages) {\n        return [`/api/chart?${params.toString()}`];\n      }\n      const query = `range=${rangeConfig.range}&interval=${rangeConfig.interval}&includePrePost=true&_=${Date.now()}`;\n      const yahooUrls = [\n        `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(symbol)}?${query}`,\n        `https://query2.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(symbol)}?${query}`\n      ];\n      return yahooUrls.flatMap(yahooUrl => [\n        yahooUrl,\n        `https://api.allorigins.win/raw?url=${encodeURIComponent(yahooUrl)}`,\n        `https://api.allorigins.win/get?url=${encodeURIComponent(yahooUrl)}`,\n        `https://corsproxy.io/?url=${encodeURIComponent(yahooUrl)}`\n      ]);\n    }\n\n    function escapeHtml(value) {\n      return String(value)\n        .replace(/&/g, \"&amp;\")\n        .replace(/</g, \"&lt;\")\n        .replace(/>/g, \"&gt;\")\n        .replace(/\"/g, \"&quot;\")\n        .replace(/'/g, \"&#039;\");\n    }\n\n    function renderOnboarding() {\n      const onboarding = document.getElementById(\"onboarding\");\n      const dashboard = document.getElementById(\"dashboard\");\n      onboarding.classList.toggle(\"hidden\", state.onboarded);\n      dashboard.classList.toggle(\"hidden\", !state.onboarded);\n      document.querySelectorAll(\".step\").forEach(step => {\n        step.classList.toggle(\"active\", Number(step.dataset.step) === currentStep);\n      });\n      document.getElementById(\"progressBar\").style.setProperty(\"--progress\", `${((currentStep + 1) / 4) * 100}%`);\n      document.getElementById(\"backBtn\").disabled = currentStep === 0;\n      document.getElementById(\"nextBtn\").textContent = currentStep === 3 ? \"Open app\" : \"Next\";\n      updateNextState();\n      if (state.onboarded) renderAll();\n    }\n\n    function updateNextState() {\n      const next = document.getElementById(\"nextBtn\");\n      let ok = true;\n      if (currentStep === 0) ok = Boolean(state.profile.reason);\n      if (currentStep === 1) ok = Number(state.profile.age) > 0;\n      if (currentStep === 2) ok = state.profile.first.trim() && state.profile.last.trim();\n      if (currentStep === 3) ok = Boolean(state.profile.level);\n      next.disabled = !ok;\n    }\n\n    function wireOnboarding() {\n      document.querySelectorAll(\"[data-choice-group]\").forEach(group => {\n        group.addEventListener(\"click\", event => {\n          const choice = event.target.closest(\".choice\");\n          if (!choice) return;\n          const key = group.dataset.choiceGroup;\n          state.profile[key] = choice.dataset.value;\n          group.querySelectorAll(\".choice\").forEach(button => button.classList.toggle(\"selected\", button === choice));\n          saveState();\n          updateNextState();\n        });\n      });\n      document.getElementById(\"ageInput\").addEventListener(\"input\", event => {\n        state.profile.age = event.target.value;\n        saveState();\n        updateNextState();\n      });\n      document.getElementById(\"firstInput\").addEventListener(\"input\", event => {\n        state.profile.first = event.target.value;\n        saveState();\n        updateNextState();\n      });\n      document.getElementById(\"lastInput\").addEventListener(\"input\", event => {\n        state.profile.last = event.target.value;\n        saveState();\n        updateNextState();\n      });\n      document.getElementById(\"backBtn\").addEventListener(\"click\", () => {\n        currentStep = Math.max(0, currentStep - 1);\n        renderOnboarding();\n      });\n      document.getElementById(\"nextBtn\").addEventListener(\"click\", () => {\n        if (currentStep < 3) {\n          currentStep += 1;\n        } else {\n          state.onboarded = true;\n          if (!state.claimed.welcome) {\n            state.claimed.welcome = true;\n            state.xp += 100;\n          }\n          saveState();\n        }\n        renderOnboarding();\n      });\n    }\n\n    function renderStats() {\n      document.getElementById(\"xpTotal\").textContent = state.xp;\n      document.getElementById(\"streakTotal\").textContent = `${state.streak} days`;\n      document.getElementById(\"levelName\").textContent = state.profile.level || \"Beginner\";\n      const first = state.profile.first || \"Investor\";\n      const last = state.profile.last ? `${state.profile.last}, ` : \"\";\n      document.getElementById(\"welcomeLine\").textContent = `${last}${first} • ${state.profile.reason || \"Learning mode\"}`;\n    }\n\n    function renderSettings() {\n      document.getElementById(\"settingsFirst\").value = state.profile.first || \"\";\n      document.getElementById(\"settingsLast\").value = state.profile.last || \"\";\n      document.getElementById(\"settingsAge\").value = state.profile.age || \"\";\n      document.getElementById(\"settingsLevel\").value = state.profile.level || \"Beginner\";\n    }\n\n    function renderMarkets() {\n      const grid = document.getElementById(\"marketGrid\");\n      grid.innerHTML = markets.map(group => `\n        <section class=\"category\">\n          <div class=\"category-head\">\n            <h3>${group.icon} ${group.category}</h3>\n          </div>\n          <div class=\"asset-list\">\n            ${group.items.map(([name, status, note, symbol, sourceUrl]) => assetTemplate(name, status, note, symbol, sourceUrl)).join(\"\")}\n          </div>\n        </section>\n      `).join(\"\");\n      renderMarketChart();\n      grid.querySelectorAll(\"[data-chart]\").forEach(row => {\n        row.addEventListener(\"click\", event => {\n          if (event.target.closest(\"[data-trade-side]\")) return;\n          const asset = findMarketAsset(row.dataset.chartName, row.dataset.chart);\n          openMarketChart(asset);\n        });\n        row.addEventListener(\"keydown\", event => {\n          if (event.key !== \"Enter\" && event.key !== \" \") return;\n          event.preventDefault();\n          const asset = findMarketAsset(row.dataset.chartName, row.dataset.chart);\n          openMarketChart(asset);\n        });\n      });\n      grid.querySelectorAll(\"[data-trade-side]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          openTradePage({\n            name: button.dataset.tradeName,\n            status: \"can\",\n            note: button.dataset.tradeNote,\n            symbol: button.dataset.tradeSymbol,\n            category: button.dataset.tradeCategory\n          }, button.dataset.tradeSide);\n        });\n      });\n    }\n\n    function assetTemplate(name, status, note, symbol, sourceUrl) {\n      const canTrade = !sourceUrl && !/index/i.test(note);\n      const displayStatus = canTrade ? \"can\" : \"cant\";\n      const label = canTrade ? \"Buy\" : \"Hold\";\n      const action = sourceUrl\n        ? `<a class=\"asset-action forge\" href=\"${escapeAttr(sourceUrl)}\" target=\"_blank\" rel=\"noopener\" aria-label=\"View ${escapeAttr(name)} on Forge\">View Forge</a>`\n        : canTrade\n          ? `<div class=\"asset-actions\">\n              <button class=\"asset-action buy\" data-trade-side=\"buy\" data-trade-name=\"${escapeAttr(name)}\" data-trade-note=\"${escapeAttr(note)}\" data-trade-symbol=\"${escapeAttr(symbol || \"\")}\" data-trade-category=\"${escapeAttr(note)}\">Buy</button>\n              <button class=\"asset-action sell\" data-trade-side=\"sell\" data-trade-name=\"${escapeAttr(name)}\" data-trade-note=\"${escapeAttr(note)}\" data-trade-symbol=\"${escapeAttr(symbol || \"\")}\" data-trade-category=\"${escapeAttr(note)}\">Sell</button>\n            </div>`\n          : `<button class=\"asset-action hold\" disabled>${label}</button>`;\n      const chartAttrs = symbol ? ` data-chart=\"${escapeAttr(symbol)}\" data-chart-name=\"${escapeAttr(name)}\" role=\"button\" tabindex=\"0\"` : \"\";\n      return `\n        <div class=\"asset ${displayStatus}${symbol ? \" has-chart\" : \"\"}\"${chartAttrs}>\n          <span class=\"marker\"></span>\n          <div><strong>${name}</strong><small>${note}</small></div>\n          ${action}\n        </div>\n      `;\n    }\n\n    function openTradePage(asset, side = \"buy\") {\n      tradeState = { asset, side, method: \"money\", amount: \"\" };\n      openMarketChart(asset);\n      document.getElementById(\"dashboard\").classList.add(\"trade-focus\");\n      renderTradePage();\n    }\n\n    function closeTradePage() {\n      tradeState = null;\n      document.getElementById(\"dashboard\").classList.remove(\"trade-focus\");\n      document.getElementById(\"tradePage\").classList.add(\"hidden\");\n      renderMarkets();\n    }\n\n    function renderTradePage() {\n      const panel = document.getElementById(\"tradePage\");\n      if (!panel || !tradeState) return;\n      panel.classList.remove(\"hidden\");\n      const { asset, side, method, amount } = tradeState;\n      const title = `${side === \"buy\" ? \"Buying\" : \"Selling\"} by ${method}`;\n      const unitLabel = method === \"money\" ? \"dollars\" : \"units\";\n      const tradePrice = getTradePrice(asset);\n      panel.innerHTML = `\n        <div class=\"trade-card\">\n          <p class=\"muted\">Paper trade</p>\n          <h2>${escapeHtml(title)}</h2>\n          <p class=\"muted\">${escapeHtml(asset.name)} ${asset.symbol ? `â€¢ ${escapeHtml(asset.symbol)}` : \"\"}</p>\n          <div class=\"trade-mode-grid\" aria-label=\"Trade type\">\n            ${[\"buy-money\", \"buy-units\", \"sell-money\", \"sell-units\"].map(key => {\n              const [modeSide, modeMethod] = key.split(\"-\");\n              const label = `${modeSide === \"buy\" ? \"Buying\" : \"Selling\"} by ${modeMethod}`;\n              return `<button class=\"trade-mode ${side === modeSide && method === modeMethod ? \"active\" : \"\"}\" data-trade-mode=\"${key}\" type=\"button\">${label}</button>`;\n            }).join(\"\")}\n          </div>\n          <label class=\"trade-amount-label\" for=\"tradeAmount\">Enter ${unitLabel}</label>\n          <input class=\"trade-amount\" id=\"tradeAmount\" type=\"number\" min=\"0\" step=\"any\" value=\"${escapeAttr(amount)}\" placeholder=\"0\" inputmode=\"decimal\" aria-label=\"Trade ${unitLabel}\">\n          <p class=\"muted\" style=\"margin-top:10px\">${tradePrice ? `Current price: ${escapeHtml(formatMarketPrice(tradePrice, \"USD\"))}` : \"Loading the current price for this trade...\"}</p>\n          <p class=\"muted\" style=\"margin-top:12px\">This is a paper trade. It changes your practice position and XP only; no real money is used.</p>\n          <div class=\"trade-confirm\">\n            <button class=\"btn green\" id=\"confirmTradeBtn\" type=\"button\">Yes</button>\n            <button class=\"btn secondary\" id=\"cancelTradeBtn\" type=\"button\">No</button>\n          </div>\n        </div>\n      `;\n      panel.querySelectorAll(\"[data-trade-mode]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          const [nextSide, nextMethod] = button.dataset.tradeMode.split(\"-\");\n          tradeState.side = nextSide;\n          tradeState.method = nextMethod;\n          renderTradePage();\n          document.getElementById(\"tradeAmount\")?.focus();\n        });\n      });\n      document.getElementById(\"tradeAmount\").addEventListener(\"input\", event => {\n        tradeState.amount = event.target.value;\n      });\n      document.getElementById(\"confirmTradeBtn\").addEventListener(\"click\", confirmTrade);\n      document.getElementById(\"cancelTradeBtn\").addEventListener(\"click\", closeTradePage);\n      document.getElementById(\"tradeAmount\").focus();\n    }\n\n    function confirmTrade() {\n      if (!tradeState) return;\n      const amount = Number(tradeState.amount);\n      if (!Number.isFinite(amount) || amount <= 0) {\n        showToast(\"Enter a number before confirming the trade.\");\n        document.getElementById(\"tradeAmount\")?.focus();\n        return;\n      }\n      const price = getTradePrice(tradeState.asset);\n      if (!price) {\n        showToast(\"Wait for the current market price, then try again.\");\n        return;\n      }\n      const units = tradeState.method === \"money\" ? amount / price : amount;\n      const dollars = tradeState.method === \"money\" ? amount : amount * price;\n      const holding = getPortfolioHolding(tradeState.asset.symbol);\n      holding.units += tradeState.side === \"buy\" ? units : -units;\n      holding.netDollars += tradeState.side === \"buy\" ? dollars : -dollars;\n      state.portfolio.holdings[tradeState.asset.symbol] = holding;\n      const label = `${tradeState.side === \"buy\" ? \"Buy\" : \"Sell\"} ${tradeState.asset.name}`;\n      state.claimed.trade = true;\n      const tradeXp = Math.round(dollars * 7) * (tradeState.side === \"buy\" ? -1 : 1);\n      saveState();\n      addXp(tradeXp, `${label} at ${formatMarketPrice(dollars, \"USD\")}`);\n      closeTradePage();\n    }\n\n    function getTradePrice(asset) {\n      if (!asset || !asset.symbol) return 0;\n      if (marketChartState.asset && marketChartState.asset.symbol === asset.symbol && marketChartState.data) {\n        const livePrice = Number(marketChartState.data.price);\n        if (Number.isFinite(livePrice) && livePrice > 0) return livePrice;\n      }\n      const cached = readMarketChartCache(asset.symbol, \"1D\");\n      const cachedPrice = cached ? Number(cached.price) : 0;\n      return Number.isFinite(cachedPrice) && cachedPrice > 0 ? cachedPrice : 0;\n    }\n\n    function getPortfolioHolding(symbol) {\n      const current = state.portfolio?.holdings?.[symbol];\n      return {\n        units: Number.isFinite(Number(current?.units)) ? Number(current.units) : 0,\n        netDollars: Number.isFinite(Number(current?.netDollars)) ? Number(current.netDollars) : 0\n      };\n    }\n\n    function escapeAttr(value) {\n      return String(value).replace(/\"/g, \"&quot;\");\n    }\n\n    function renderCourse() {\n      const path = document.getElementById(\"coursePath\");\n      const panel = document.getElementById(\"lessonPanel\");\n      const doneCount = courseUnits.filter(unit => state.completed[unit.id]).length;\n      const nextUnit = courseUnits.find(unit => !state.completed[unit.id]) || courseUnits[courseUnits.length - 1];\n      const activeUnit = getActiveCourseUnit(nextUnit);\n\n      document.getElementById(\"courseDone\").textContent = `${doneCount}/${courseUnits.length}`;\n      document.getElementById(\"coursePercent\").textContent = `${Math.round((doneCount / courseUnits.length) * 100)}%`;\n      document.getElementById(\"courseNext\").textContent = nextUnit ? nextUnit.title : \"Complete\";\n\n      panel.innerHTML = lessonPanelTemplate(activeUnit);\n      path.innerHTML = courseUnits.map((unit, index) => {\n        const done = Boolean(state.completed[unit.id]);\n        const unlocked = isCourseUnlocked(index);\n        const current = activeUnit.id === unit.id;\n        const icon = done ? \"✓\" : unit.kind === \"quiz\" ? \"?\" : unit.kind === \"test\" ? \"T\" : unit.kind === \"course\" ? \"★\" : index + 1;\n        return `\n          <button class=\"course-node ${done ? \"done\" : \"\"} ${current ? \"current\" : \"\"} ${unlocked ? \"\" : \"locked\"}\" data-course=\"${unit.id}\" ${unlocked ? \"\" : \"disabled\"}>\n            <span class=\"node-icon\">${icon}</span>\n            <span>\n              <strong>${unit.title}</strong>\n              <span class=\"muted\" style=\"display:block\">${courseTypeLabel(unit)}${done ? \" • done\" : unlocked ? \" • unlocked\" : \" • locked\"}</span>\n            </span>\n            <span class=\"xp\">+${courseXpTotal(unit)} XP</span>\n          </button>\n        `;\n      }).join(\"\");\n\n      panel.querySelectorAll(\"[data-complete-unit]\").forEach(button => {\n        button.addEventListener(\"click\", () => completeCourseUnit(button.dataset.completeUnit, false));\n      });\n      panel.querySelectorAll(\"[data-answer]\").forEach(button => {\n        button.addEventListener(\"click\", () => checkCourseAnswer(button.dataset.unit, Number(button.dataset.answer)));\n      });\n      path.querySelectorAll(\"[data-course]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          state.activeCourseId = button.dataset.course;\n          saveState();\n          renderCourse();\n        });\n      });\n      renderStreaks();\n    }\n\n    function getActiveCourseUnit(nextUnit) {\n      const saved = courseUnits.find(unit => unit.id === state.activeCourseId);\n      if (saved && isCourseUnlocked(courseUnits.indexOf(saved))) return saved;\n      state.activeCourseId = nextUnit.id;\n      return nextUnit;\n    }\n\n    function isCourseUnlocked(index) {\n      if (index === 0) return true;\n      return Boolean(state.completed[courseUnits[index - 1].id]);\n    }\n\n    function courseTypeLabel(unit) {\n      if (unit.kind === \"quiz\") return \"Quiz\";\n      if (unit.kind === \"test\") return \"Test\";\n      if (unit.kind === \"course\") return \"Course bonus\";\n      return \"Lesson\";\n    }\n\n    function courseXpTotal(unit) {\n      return unit.xp + (unit.perfectXp || 0);\n    }\n\n    function lessonPanelTemplate(unit) {\n      const done = Boolean(state.completed[unit.id]);\n      const doneText = done ? `<span class=\"xp\">Completed</span>` : \"\";\n      if (unit.kind === \"quiz\" || unit.kind === \"test\") {\n        return `\n          <div class=\"section-head\" style=\"margin-bottom:0\">\n            <div>\n              <h3>${unit.title}</h3>\n              <p class=\"muted\">${courseTypeLabel(unit)} • +${unit.xp} XP${unit.perfectXp ? ` • +${unit.perfectXp} perfect XP` : \"\"}</p>\n            </div>\n            ${doneText}\n          </div>\n          <p class=\"lesson-body\">${unit.question}</p>\n          <div class=\"quiz-options\">\n            ${unit.options.map((option, index) => `<button class=\"quiz-option\" data-unit=\"${unit.id}\" data-answer=\"${index}\" ${done ? \"disabled\" : \"\"}>${option}</button>`).join(\"\")}\n          </div>\n        `;\n      }\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${unit.title}</h3>\n            <p class=\"muted\">${courseTypeLabel(unit)} • +${unit.xp} XP</p>\n          </div>\n          ${doneText}\n        </div>\n        <p class=\"lesson-body\">${unit.body}</p>\n        <button class=\"btn green\" data-complete-unit=\"${unit.id}\" ${done ? \"disabled\" : \"\"}>${unit.kind === \"course\" ? \"Collect course XP\" : \"Finish lesson\"}</button>\n      `;\n    }\n\n    function completeCourseUnit(unitId, perfect) {\n      const unit = courseUnits.find(item => item.id === unitId);\n      if (!unit || state.completed[unit.id]) return;\n      state.completed[unit.id] = true;\n      state.streak += 1;\n      addXp(unit.xp, unit.title);\n      if (perfect && unit.perfectXp) addXp(unit.perfectXp, `${unit.title} perfect score`);\n      if (unit.id === \"module-test\" && !state.claimed.moduleComplete) {\n        state.claimed.moduleComplete = true;\n        addXp(150, \"learning module\");\n      }\n      state.activeCourseId = (courseUnits[courseUnits.indexOf(unit) + 1] || unit).id;\n      saveState();\n      renderAll();\n    }\n\n    function checkCourseAnswer(unitId, answerIndex) {\n      const unit = courseUnits.find(item => item.id === unitId);\n      if (!unit || state.completed[unit.id]) return;\n      const panel = document.getElementById(\"lessonPanel\");\n      panel.querySelectorAll(\"[data-answer]\").forEach(button => {\n        const isCorrect = Number(button.dataset.answer) === unit.answer;\n        button.classList.toggle(\"correct\", isCorrect);\n        button.classList.toggle(\"wrong\", Number(button.dataset.answer) === answerIndex && !isCorrect);\n        button.disabled = true;\n      });\n      if (answerIndex === unit.answer) {\n        completeCourseUnit(unit.id, true);\n      } else {\n        addXp(6, \"review try\");\n        window.setTimeout(renderCourse, 900);\n      }\n    }\n\n    function renderStreaks() {\n      const grid = document.getElementById(\"streakGrid\");\n      grid.innerHTML = streakRewards.map(([days, xp]) => {\n        const id = `streak${days}`;\n        const ready = state.streak >= days && !state.claimed[id];\n        const claimed = state.claimed[id];\n        return `\n          <button class=\"streak ${claimed ? \"claimed\" : \"\"}\" data-streak=\"${days}\" ${ready ? \"\" : \"disabled\"}>\n            <strong>🔥 ${days}-day streak</strong>\n            <span class=\"muted\">+${xp} XP</span>\n          </button>\n        `;\n      }).join(\"\");\n      grid.querySelectorAll(\"[data-streak]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          const days = Number(button.dataset.streak);\n          const reward = streakRewards.find(item => item[0] === days);\n          const id = `streak${days}`;\n          if (!reward || state.claimed[id] || state.streak < days) return;\n          state.claimed[id] = true;\n          addXp(reward[1], `${days}-day streak`);\n          saveState();\n          renderAll();\n        });\n      });\n    }\n\n    function renderCourse() {\n      const path = document.getElementById(\"coursePath\");\n      const panel = document.getElementById(\"lessonPanel\");\n      const doneCount = courseItems.filter(item => state.completed[item.id]).length;\n      const nextItem = courseItems.find(item => !state.completed[item.id]) || courseItems[courseItems.length - 1];\n      const activeItem = getActiveCourseItem(nextItem);\n      const learnPanel = document.querySelector('[data-panel=\"learn\"]');\n      const activeProgress = activeItem.kind === \"module\" ? getProgress(activeItem.id) : null;\n      const lessonMode = !learnPanel.classList.contains(\"hidden\") && activeItem.kind === \"module\" && !activeProgress.lessonDone && !activeProgress.activityResult && !courseOverviewMode;\n      document.querySelector('[data-panel=\"learn\"]').classList.toggle(\"lesson-mode\", lessonMode);\n      document.getElementById(\"dashboard\").classList.toggle(\"lesson-focus\", lessonMode);\n\n      document.getElementById(\"courseDone\").textContent = `${doneCount}/${courseItems.length}`;\n      document.getElementById(\"coursePercent\").textContent = `${Math.round((doneCount / courseItems.length) * 100)}%`;\n      document.getElementById(\"courseNext\").textContent = nextItem ? nextItem.title : \"Complete\";\n\n      panel.innerHTML = coursePanelTemplate(activeItem);\n      path.innerHTML = courseItems.map((item, index) => {\n        const done = Boolean(state.completed[item.id]);\n        const unlocked = isCourseUnlocked(index);\n        const current = activeItem.id === item.id;\n        const icon = done ? \"OK\" : item.kind === \"bigTest\" ? \"T\" : item.kind === \"course\" ? \"$\" : item.number;\n        return `\n          <button class=\"course-node ${done ? \"done\" : \"\"} ${current ? \"current\" : \"\"} ${unlocked ? \"\" : \"locked\"}\" data-course=\"${item.id}\" ${unlocked ? \"\" : \"disabled\"}>\n            <span class=\"node-icon\">${icon}</span>\n            <span>\n              <strong>${item.title}</strong>\n              <span class=\"muted\" style=\"display:block\">${courseTypeLabel(item)}${done ? \" - done\" : unlocked ? \" - unlocked\" : \" - locked\"}</span>\n            </span>\n            <span class=\"xp\">Up to +${courseXpTotal(item)} XP</span>\n          </button>\n        `;\n      }).join(\"\");\n\n      panel.querySelectorAll(\"[data-next-lesson]\").forEach(button => {\n        button.addEventListener(\"click\", () => advanceLesson(button.dataset.nextLesson));\n      });\n      panel.querySelectorAll(\"[data-quit-lesson]\").forEach(button => {\n        button.addEventListener(\"click\", () => quitCurrentLesson(button.dataset.quitLesson));\n      });\n      panel.querySelectorAll(\"[data-start-module-skip]\").forEach(button => {\n        button.addEventListener(\"click\", () => startModuleSkip(button.dataset.startModuleSkip));\n      });\n      panel.querySelectorAll(\"[data-skip-answer]\").forEach(button => {\n        button.addEventListener(\"click\", () => answerModuleSkip(button.dataset.module, Number(button.dataset.skipAnswer)));\n      });\n      panel.querySelectorAll(\"[data-lesson-answer]\").forEach(button => {\n        button.addEventListener(\"click\", () => answerLessonQuestion(button.dataset.module, Number(button.dataset.lessonAnswer), Number(button.dataset.page)));\n      });\n      panel.querySelectorAll(\"[data-answer]\").forEach(button => {\n        button.addEventListener(\"click\", () => answerCourseQuestion(button.dataset.item, Number(button.dataset.answer)));\n      });\n      panel.querySelectorAll(\"[data-continue-result]\").forEach(button => {\n        button.addEventListener(\"click\", () => continueCourseResult(button.dataset.continueResult));\n      });\n      panel.querySelectorAll(\"[data-collect-course]\").forEach(button => {\n        button.addEventListener(\"click\", () => collectCourseBonus());\n      });\n      path.querySelectorAll(\"[data-course]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          state.activeCourseId = button.dataset.course;\n          courseOverviewMode = false;\n          saveState();\n          renderCourse();\n        });\n      });\n      syncSkipChallengeTimer(activeItem);\n      renderStreaks();\n    }\n\n    function getActiveCourseItem(nextItem) {\n      const saved = courseItems.find(item => item.id === state.activeCourseId);\n      if (saved && isCourseUnlocked(courseItems.indexOf(saved))) return saved;\n      state.activeCourseId = nextItem.id;\n      return nextItem;\n    }\n\n    function isCourseUnlocked(index) {\n      if (index === 0) return true;\n      return Boolean(state.completed[courseItems[index - 1].id]);\n    }\n\n    function courseTypeLabel(item) {\n      if (item.kind === \"bigTest\") return \"30-question big test\";\n      if (item.kind === \"course\") return \"Course bonus\";\n      return \"10 lessons, each with 1 lecture + 8 questions\";\n    }\n\n    function courseXpTotal(item) {\n      if (item.kind === \"module\") return (item.lessonXp * item.lessons.length) + item.quizXp + item.perfectXp + item.moduleXp;\n      if (item.kind === \"bigTest\") return item.xp + item.perfectXp;\n      return item.xp;\n    }\n\n    function getProgress(itemId) {\n      const defaults = {\n        lessonIndex: 0,\n        completedLessons: 0,\n        queueLessonIndex: null,\n        lessonPage: 0,\n        lessonDone: false,\n        lessonQueue: null,\n        lessonRetryQueue: [],\n        lessonCorrect: [],\n        lessonMisses: [],\n        lessonStartedAt: 0,\n        lastMiss: null,\n        quizIndex: 0,\n        quizCorrect: 0,\n        quizAnswered: 0,\n        quizStartedAt: 0,\n        quizDone: false,\n        testIndex: 0,\n        testCorrect: 0,\n        testAnswered: 0,\n        testStartedAt: 0,\n        testDone: false,\n        skipActive: false,\n        skipped: false,\n        skipIndex: 0,\n        skipCorrect: 0,\n        skipMisses: 0,\n        skipStartedAt: 0,\n        skipEligible: false,\n        activityResult: null\n      };\n      state.courseProgress[itemId] = { ...defaults, ...(state.courseProgress[itemId] || {}) };\n      const progress = state.courseProgress[itemId];\n      if (Number(progress.completedLessons || 0) > 0 && !progress.lessonDone && !progress.skipped) {\n        progress.skipEligible = true;\n      }\n      return progress;\n    }\n\n    function currentLesson(module, progress) {\n      const lessons = module.lessons || [{ id: `${module.id}-lesson-1`, number: 1, title: \"Lesson 1\", pages: module.lessonPages }];\n      const requestedIndex = Number(progress.lessonIndex) || 0;\n      const index = Math.max(0, Math.min(requestedIndex, lessons.length - 1));\n      return { lesson: lessons[index], index, total: lessons.length };\n    }\n\n    function lessonPagesFor(module, progress) {\n      return currentLesson(module, progress).lesson.pages;\n    }\n\n    function coursePanelTemplate(item) {\n      if (item.kind === \"module\") return modulePanelTemplate(item);\n      if (item.kind === \"bigTest\") return testPanelTemplate(item);\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${item.title}</h3>\n            <p class=\"muted\">${item.body}</p>\n          </div>\n        </div>\n        <button class=\"btn green\" data-collect-course ${state.completed[item.id] ? \"disabled\" : \"\"}>Collect +${item.xp} XP</button>\n      `;\n    }\n\n    function modulePanelTemplate(module) {\n      const progress = getProgress(module.id);\n      if (progress.activityResult) return activityResultTemplate(module, progress.activityResult);\n      if (progress.skipActive) return moduleSkipTemplate(module, progress);\n      if (!progress.lessonDone) return lessonTemplate(module, progress);\n      if (!progress.quizDone) return questionSetTemplate(module, module.quizQuestions, progress.quizIndex, progress.quizCorrect, \"quiz\");\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${module.title}</h3>\n            <p class=\"muted\">${progress.skipped ? \"Module skip challenge passed.\" : \"All 10 lessons complete. Quiz complete. Module bonus collected.\"}</p>\n          </div>\n          <span class=\"xp\">Done</span>\n        </div>\n        ${progress.skipped ? `<p class=\"lesson-body\">You passed the 30-question skip challenge. The next module or big test is unlocked.</p>` : `${moduleStatusTemplate(module, progress)}<p class=\"lesson-body\">Great work. The next module or big test is unlocked.</p>`}\n        <button class=\"btn secondary\" disabled>Module complete</button>\n      `;\n    }\n\n    function lessonTemplate(module, progress) {\n      const lessonInfo = currentLesson(module, progress);\n      const pages = lessonPagesFor(module, progress);\n      const queue = getLessonQueue(module, progress);\n      const retryQueue = getLessonRetryQueue(progress);\n      const pageIndex = queue[0] ?? retryQueue[0] ?? pages.length - 1;\n      const page = pages[pageIndex];\n      const stepText = `${Math.min(progress.lessonPage + 1, pages.length)}/${pages.length}`;\n      const practiceTotal = lessonPracticeTotal(module, progress);\n      const missPanel = progress.lastMiss ? missedQuestionTemplate(progress.lastMiss) : \"\";\n      if (page.type === \"practice\") return practiceSetTemplate(module, progress, queue, practiceTotal, missPanel);\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${module.title}</h3>\n            <p class=\"muted\">${lessonInfo.lesson.title} - lecture page - page ${stepText}</p>\n          </div>\n          <span class=\"xp\">Up to +${module.lessonXp} XP</span>\n        </div>\n        ${moduleStatusTemplate(module, progress)}\n        ${missPanel}\n        <div class=\"lesson-step\">\n          <strong>${page.title}</strong>\n          <p class=\"lesson-body\">${page.body}</p>\n        </div>\n        <div class=\"actions\">\n          <button class=\"btn green\" data-next-lesson=\"${module.id}\">Start 8 questions</button>\n          ${canSkipModule(progress) ? `<button class=\"btn secondary\" data-start-module-skip=\"${module.id}\">Skip module: 30-question challenge</button>` : \"\"}\n          <button class=\"btn secondary\" data-quit-lesson=\"${module.id}\">Quit lesson</button>\n        </div>\n      `;\n    }\n\n    function moduleStatusTemplate(module, progress) {\n      const lessonInfo = currentLesson(module, progress);\n      if (!progress.lessonDone) getLessonQueue(module, progress);\n      const practiceTotal = lessonPracticeTotal(module, progress);\n      const completedLessons = progress.lessonDone ? lessonInfo.total : Math.min(progress.completedLessons || 0, lessonInfo.total);\n      const correctThisLesson = progress.lessonDone ? practiceTotal : progress.lessonCorrect.length;\n      const retryCount = getLessonRetryQueue(progress).length;\n      return `\n        <div class=\"module-status\">\n          <span class=\"mini-pill ${progress.lessonDone ? \"done\" : \"\"}\">Lessons ${completedLessons}/${lessonInfo.total}</span>\n          <span class=\"mini-pill ${progress.lessonDone ? \"done\" : \"\"}\">Current lesson ${progress.lessonDone ? lessonInfo.total : lessonInfo.index + 1}/${lessonInfo.total}</span>\n          <span class=\"mini-pill ${correctThisLesson === practiceTotal ? \"done\" : \"\"}\">Questions ${correctThisLesson}/${practiceTotal}</span>\n          <span class=\"mini-pill ${retryCount ? \"\" : \"done\"}\">Waiting to retry ${retryCount}</span>\n          <span class=\"mini-pill ${progress.quizDone ? \"done\" : \"\"}\">Quiz ${Math.min(progress.quizIndex, module.quizQuestions.length)}/${module.quizQuestions.length}</span>\n          <span class=\"mini-pill ${state.completed[module.id] ? \"done\" : \"\"}\">Module +${module.moduleXp} XP</span>\n        </div>\n      `;\n    }\n\n    function practiceSetTemplate(module, progress, queue, practiceTotal, missPanel) {\n      const lessonInfo = currentLesson(module, progress);\n      const pages = lessonPagesFor(module, progress);\n      const pendingPractice = queue.filter(index => pages[index]?.type === \"practice\");\n      const retryPractice = getLessonRetryQueue(progress).filter(index => pages[index]?.type === \"practice\");\n      const isRetryRound = pendingPractice.length === 0 && retryPractice.length > 0;\n      const pageIndex = (isRetryRound ? retryPractice : pendingPractice)[0];\n      const practice = pages[pageIndex];\n      const questionNumber = Math.max(1, pageIndex);\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${module.title}</h3>\n            <p class=\"muted\">${lessonInfo.lesson.title} - ${isRetryRound ? \"retry round\" : `question ${questionNumber} of ${practiceTotal}`}</p>\n          </div>\n          <span class=\"xp\">Up to +${module.lessonXp} XP</span>\n        </div>\n        ${moduleStatusTemplate(module, progress)}\n        ${missPanel}\n        <div class=\"lesson-step\">\n          <div class=\"question-meta\">\n            <strong>${isRetryRound ? \"Retry\" : \"Question\"} ${questionNumber}/${practiceTotal}</strong>\n            <span class=\"mini-pill\">${pendingPractice.length} new left</span>\n            <span class=\"mini-pill\">${retryPractice.length} to retry</span>\n            <span class=\"mini-pill\">${practice.style}</span>\n          </div>\n          <p class=\"lesson-body\">${practice.prompt}</p>\n          <div class=\"quiz-options\">\n            ${practice.options.map((option, index) => `<button class=\"quiz-option\" data-module=\"${module.id}\" data-page=\"${pageIndex}\" data-lesson-answer=\"${index}\">${option}</button>`).join(\"\")}\n          </div>\n        </div>\n        <div class=\"actions\">\n          ${canSkipModule(progress) ? `<button class=\"btn secondary\" data-start-module-skip=\"${module.id}\">Skip module: 30-question challenge</button>` : \"\"}\n          <button class=\"btn secondary\" data-quit-lesson=\"${module.id}\">Quit lesson</button>\n        </div>\n      `;\n    }\n\n    function canSkipModule(progress) {\n      return !progress.skipped && !progress.lessonDone && progress.skipEligible === true;\n    }\n\n    function moduleSkipTemplate(module, progress) {\n      const question = module.skipQuestions[progress.skipIndex];\n      if (!question) return \"\";\n      const remaining = skipTimeRemaining(progress);\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${module.title} skip challenge</h3>\n            <p class=\"muted\">30 mixed questions from this module's 10 lessons. Wrong answers do not return.</p>\n          </div>\n          <span class=\"xp\">+${SKIP_REWARD_XP} XP</span>\n        </div>\n        <div class=\"module-status\">\n          <span class=\"mini-pill\">Question ${progress.skipIndex + 1}/${SKIP_QUESTION_COUNT}</span>\n          <span class=\"mini-pill\">Correct ${progress.skipCorrect}</span>\n          <span class=\"mini-pill ${progress.skipMisses ? \"\" : \"done\"}\">Misses ${progress.skipMisses}/${SKIP_MISS_LIMIT}</span>\n          <span class=\"mini-pill\" data-skip-time>${formatCountdown(remaining)}</span>\n        </div>\n        <div class=\"lesson-step\">\n          <div class=\"question-meta\">\n            <strong>${question.sourceLesson}</strong>\n            <span class=\"mini-pill\">${question.style}</span>\n          </div>\n          <p class=\"lesson-body\">${question.prompt}</p>\n          <div class=\"quiz-options\">\n            ${question.options.map((option, optionIndex) => `<button class=\"quiz-option\" data-module=\"${module.id}\" data-skip-answer=\"${optionIndex}\">${option}</button>`).join(\"\")}\n          </div>\n        </div>\n      `;\n    }\n\n    function missedQuestionTemplate(miss) {\n      return `\n        <div class=\"miss-panel\">\n          <strong>Question ${miss.questionNumber} moved to the retry round.</strong>\n          <p class=\"muted\">The remaining new questions come first. This question returns afterward.</p>\n          <details>\n            <summary>Show answer and explanation</summary>\n            <p class=\"lesson-body\"><strong>Answer:</strong> ${miss.answer}</p>\n            <p class=\"lesson-body\">${miss.explanation}</p>\n          </details>\n        </div>\n      `;\n    }\n\n    function getLessonQueue(module, progress) {\n      const lessonInfo = currentLesson(module, progress);\n      const pages = lessonPagesFor(module, progress);\n      if (progress.queueLessonIndex !== lessonInfo.index) {\n        progress.queueLessonIndex = lessonInfo.index;\n        progress.lessonPage = 0;\n        progress.lessonQueue = null;\n        progress.lessonRetryQueue = [];\n        progress.lessonCorrect = [];\n        progress.lessonMisses = [];\n        progress.lastMiss = null;\n      }\n      if (!Array.isArray(progress.lessonQueue)) {\n        progress.lessonQueue = pages.map((_, index) => index);\n      }\n      if (!Array.isArray(progress.lessonRetryQueue)) progress.lessonRetryQueue = [];\n      if (!Array.isArray(progress.lessonCorrect)) progress.lessonCorrect = [];\n      if (!Array.isArray(progress.lessonMisses)) progress.lessonMisses = [];\n      return progress.lessonQueue;\n    }\n\n    function getLessonRetryQueue(progress) {\n      if (!Array.isArray(progress.lessonRetryQueue)) progress.lessonRetryQueue = [];\n      return progress.lessonRetryQueue;\n    }\n\n    function lessonPracticeTotal(module, progress) {\n      return lessonPagesFor(module, progress).filter(page => page.type === \"practice\").length;\n    }\n\n    function testPanelTemplate(test) {\n      const progress = getProgress(test.id);\n      if (progress.activityResult) return activityResultTemplate(test, progress.activityResult);\n      if (state.completed[test.id]) {\n        return `\n          <div class=\"section-head\" style=\"margin-bottom:0\">\n            <div>\n              <h3>${test.title}</h3>\n              <p class=\"muted\">Completed with ${progress.testCorrect}/${test.questions.length} correct.</p>\n            </div>\n            <span class=\"xp\">Done</span>\n          </div>\n          <p class=\"lesson-body\">The next module is unlocked.</p>\n        `;\n      }\n      return questionSetTemplate(test, test.questions, progress.testIndex, progress.testCorrect, \"bigTest\");\n    }\n\n    function questionSetTemplate(item, questions, index, correct, mode) {\n      const progress = getProgress(item.id);\n      ensureActivityTimer(progress, mode === \"quiz\" ? \"quizStartedAt\" : \"testStartedAt\");\n      const question = questions[index] || questions[questions.length - 1];\n      const label = question.type === \"sim\" ? \"Simulation\" : \"Multiple choice\";\n      const progressText = `${Math.min(index + 1, questions.length)}/${questions.length}`;\n      const mcCount = mode === \"bigTest\" ? 21 : 10;\n      const simCount = mode === \"bigTest\" ? 9 : 5;\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${item.title}</h3>\n            <p class=\"muted\">${mode === \"quiz\" ? \"Quiz\" : \"Big test\"} - ${mcCount} multiple choice, ${simCount} simulation</p>\n          </div>\n          <span class=\"xp\">Score ${correct}/${questions.length}</span>\n        </div>\n        ${item.kind === \"module\" ? moduleStatusTemplate(item, getProgress(item.id)) : \"\"}\n        <div class=\"lesson-step\">\n          <div class=\"question-meta\">\n            <strong>${label} ${progressText}</strong>\n            <span class=\"mini-pill\">${mode === \"quiz\" ? \"Up to +60 XP\" : \"Up to +150 XP\"}</span>\n          </div>\n          <p class=\"lesson-body\">${question.prompt}</p>\n          <div class=\"quiz-options\">\n            ${question.options.map((option, optionIndex) => `<button class=\"quiz-option\" data-item=\"${item.id}\" data-answer=\"${optionIndex}\">${option}</button>`).join(\"\")}\n          </div>\n        </div>\n      `;\n    }\n\n    function ensureActivityTimer(progress, key) {\n      const learnPanel = document.querySelector('[data-panel=\"learn\"]');\n      if (!learnPanel || learnPanel.classList.contains(\"hidden\") || progress[key]) return;\n      progress[key] = Date.now();\n      saveState();\n    }\n\n    function performanceReward(maxXp, correct, total, durationMs) {\n      const halfXp = maxXp / 2;\n      const accuracyXp = total ? halfXp * (correct / total) : 0;\n      const elapsedSeconds = Math.floor(durationMs / 1000);\n      const overtimeSeconds = Math.max(0, elapsedSeconds - 120);\n      const speedXp = Math.max(0, halfXp - overtimeSeconds);\n      return {\n        accuracyXp,\n        speedXp,\n        overtimeSeconds,\n        totalXp: Math.round(accuracyXp + speedXp)\n      };\n    }\n\n    function formatXpPart(value) {\n      return Number.isInteger(value) ? String(value) : value.toFixed(1);\n    }\n\n    function elapsedTime(startedAt) {\n      const start = Number(startedAt) || Date.now();\n      return Math.max(1000, Date.now() - start);\n    }\n\n    function formatDuration(durationMs) {\n      const totalSeconds = Math.max(1, Math.round(durationMs / 1000));\n      const minutes = Math.floor(totalSeconds / 60);\n      const seconds = totalSeconds % 60;\n      if (!minutes) return `${seconds} sec`;\n      if (!seconds) return `${minutes} min`;\n      return `${minutes} min ${seconds} sec`;\n    }\n\n    function formatCountdown(durationMs) {\n      const totalSeconds = Math.max(0, Math.ceil(durationMs / 1000));\n      const minutes = Math.floor(totalSeconds / 60);\n      const seconds = totalSeconds % 60;\n      return `${minutes}:${String(seconds).padStart(2, \"0\")} left`;\n    }\n\n    function skipTimeRemaining(progress) {\n      const startedAt = Number(progress.skipStartedAt) || Date.now();\n      return Math.max(0, SKIP_TIME_LIMIT_MS - (Date.now() - startedAt));\n    }\n\n    function syncSkipChallengeTimer(activeItem) {\n      window.clearInterval(skipChallengeTimer);\n      skipChallengeTimer = 0;\n      if (!activeItem || activeItem.kind !== \"module\") return;\n      const progress = getProgress(activeItem.id);\n      if (!progress.skipActive) return;\n      const update = () => {\n        const current = getProgress(activeItem.id);\n        if (!current.skipActive) {\n          window.clearInterval(skipChallengeTimer);\n          skipChallengeTimer = 0;\n          return;\n        }\n        const remaining = skipTimeRemaining(current);\n        const timer = document.querySelector(\"[data-skip-time]\");\n        if (timer) timer.textContent = formatCountdown(remaining);\n        if (remaining <= 0) finishModuleSkip(activeItem, current, \"time\");\n      };\n      update();\n      if (progress.skipActive) skipChallengeTimer = window.setInterval(update, 250);\n    }\n\n    function activityResultTemplate(item, result) {\n      const skipAction = item.kind === \"module\" && canSkipModule(getProgress(item.id))\n        ? `<button class=\"btn secondary\" data-start-module-skip=\"${item.id}\">Skip module: 30-question challenge</button>`\n        : \"\";\n      return `\n        <div class=\"section-head\" style=\"margin-bottom:0\">\n          <div>\n            <h3>${result.title}</h3>\n            <p class=\"muted\">${result.failed ? \"The module was not skipped. You can return to its lessons or try the challenge again.\" : \"Finished. Here is your complete result.\"}</p>\n          </div>\n          <span class=\"xp\">${result.totalXp ? `+${result.totalXp}` : \"0\"} XP earned</span>\n        </div>\n        <div class=\"result-summary\">\n          <div class=\"result-grid\">\n            <div class=\"result-stat\">\n              <span>Accuracy</span>\n              <strong>${result.accuracy}%</strong>\n            </div>\n            <div class=\"result-stat\">\n              <span>Correct answers</span>\n              <strong>${result.correct}/${result.total}</strong>\n            </div>\n            <div class=\"result-stat\">\n              <span>Time used</span>\n              <strong>${formatDuration(result.durationMs)}</strong>\n            </div>\n            <div class=\"result-stat\">\n              <span>XP earned</span>\n              <strong>+${result.totalXp}</strong>\n            </div>\n          </div>\n          <p class=\"lesson-body\">${result.xpNote}</p>\n          <div class=\"actions\">\n            <button class=\"btn green\" data-continue-result=\"${item.id}\">${result.nextLabel}</button>\n            ${skipAction}\n          </div>\n        </div>\n      `;\n    }\n\n    function advanceLesson(moduleId) {\n      const module = courseModules.find(item => item.id === moduleId);\n      if (!module || state.completed[module.id]) return;\n      courseOverviewMode = false;\n      const progress = getProgress(module.id);\n      const pages = lessonPagesFor(module, progress);\n      const queue = getLessonQueue(module, progress);\n      const firstQuestionClick = progress.lessonPage === 0 && queue.length === pages.length;\n      if (firstQuestionClick || !progress.lessonStartedAt) progress.lessonStartedAt = Date.now();\n      progress.lastMiss = null;\n      queue.shift();\n      progress.lessonPage += 1;\n      if (!queue.length) {\n        finishLesson(module, progress);\n      } else {\n        saveState();\n        renderCourse();\n      }\n    }\n\n    function startModuleSkip(moduleId) {\n      const module = courseModules.find(item => item.id === moduleId);\n      if (!module || state.completed[module.id]) return;\n      const progress = getProgress(module.id);\n      if (!canSkipModule(progress)) {\n        showToast(\"Finish a lesson, then choose the skip challenge from its results screen.\");\n        return;\n      }\n      courseOverviewMode = false;\n      progress.skipActive = true;\n      progress.skipIndex = 0;\n      progress.skipCorrect = 0;\n      progress.skipMisses = 0;\n      progress.skipStartedAt = Date.now();\n      progress.activityResult = null;\n      saveState();\n      renderCourse();\n    }\n\n    function quitCurrentLesson(moduleId) {\n      const module = courseModules.find(item => item.id === moduleId);\n      if (!module || state.completed[module.id]) return;\n      const progress = getProgress(module.id);\n      progress.queueLessonIndex = null;\n      progress.lessonPage = 0;\n      progress.lessonQueue = null;\n      progress.lessonRetryQueue = [];\n      progress.lessonCorrect = [];\n      progress.lessonMisses = [];\n      progress.lessonStartedAt = 0;\n      progress.lastMiss = null;\n      courseOverviewMode = true;\n      saveState();\n      renderCourse();\n      showToast(\"Lesson quit. No XP was awarded.\");\n    }\n\n    function markSkipAnswerButtons(answerIndex, correctIndex) {\n      const panel = document.getElementById(\"lessonPanel\");\n      panel.querySelectorAll(\"[data-skip-answer]\").forEach(button => {\n        const isCorrect = Number(button.dataset.skipAnswer) === correctIndex;\n        button.classList.toggle(\"correct\", isCorrect);\n        button.classList.toggle(\"wrong\", Number(button.dataset.skipAnswer) === answerIndex && !isCorrect);\n        button.disabled = true;\n      });\n    }\n\n    function answerModuleSkip(moduleId, answerIndex) {\n      const module = courseModules.find(item => item.id === moduleId);\n      if (!module || state.completed[module.id]) return;\n      const progress = getProgress(module.id);\n      if (!progress.skipActive) return;\n      if (skipTimeRemaining(progress) <= 0) {\n        finishModuleSkip(module, progress, \"time\");\n        return;\n      }\n      const question = module.skipQuestions[progress.skipIndex];\n      if (!question) return;\n      markSkipAnswerButtons(answerIndex, question.answer);\n      const correct = answerIndex === question.answer;\n      progress.skipIndex += 1;\n      if (correct) progress.skipCorrect += 1;\n      else progress.skipMisses += 1;\n      saveState();\n      window.setTimeout(() => {\n        if (progress.skipMisses >= SKIP_MISS_LIMIT) {\n          finishModuleSkip(module, progress, \"misses\");\n        } else if (progress.skipIndex >= module.skipQuestions.length) {\n          finishModuleSkip(module, progress, \"passed\");\n        } else {\n          renderCourse();\n        }\n      }, 450);\n    }\n\n    function finishModuleSkip(module, progress, outcome) {\n      if (!progress.skipActive) return;\n      window.clearInterval(skipChallengeTimer);\n      skipChallengeTimer = 0;\n      const answered = Math.min(progress.skipIndex, module.skipQuestions.length);\n      const accuracy = answered ? Math.round((progress.skipCorrect / answered) * 100) : 0;\n      const durationMs = elapsedTime(progress.skipStartedAt);\n      progress.skipActive = false;\n      if (outcome === \"passed\") {\n        progress.skipped = true;\n        progress.lessonDone = true;\n        progress.quizDone = true;\n        progress.completedLessons = 0;\n        state.completed[module.id] = true;\n        state.streak += 1;\n        addXp(SKIP_REWARD_XP, `${module.shortTitle} skip challenge`);\n        progress.activityResult = {\n          kind: \"moduleSkip\",\n          title: `${module.shortTitle} skip challenge passed`,\n          correct: progress.skipCorrect,\n          total: SKIP_QUESTION_COUNT,\n          accuracy,\n          durationMs,\n          totalXp: SKIP_REWARD_XP,\n          xpNote: `You finished all ${SKIP_QUESTION_COUNT} mixed questions with ${progress.skipMisses}/${SKIP_MISS_LIMIT} misses. This module is now marked as skipped.`,\n          nextLabel: \"Continue course\"\n        };\n      } else {\n        const reason = outcome === \"time\" ? \"The five-minute timer ended.\" : `You reached ${SKIP_MISS_LIMIT} misses.`;\n        progress.activityResult = {\n          kind: \"skipFailed\",\n          title: `${module.shortTitle} skip challenge ended`,\n          correct: progress.skipCorrect,\n          total: answered,\n          accuracy,\n          durationMs,\n          totalXp: 0,\n          failed: true,\n          xpNote: `${reason} Wrong questions do not return, and no XP was awarded.`,\n          nextLabel: \"Back to module\"\n        };\n      }\n      saveState();\n      renderAll();\n    }\n\n    function answerLessonQuestion(moduleId, answerIndex, pageIndex) {\n      const module = courseModules.find(item => item.id === moduleId);\n      if (!module || state.completed[module.id]) return;\n      const progress = getProgress(module.id);\n      if (!progress.lessonStartedAt) progress.lessonStartedAt = Date.now();\n      const queue = getLessonQueue(module, progress);\n      const retryQueue = getLessonRetryQueue(progress);\n      const page = lessonPagesFor(module, progress)[pageIndex];\n      const queuePosition = queue.indexOf(pageIndex);\n      const retryPosition = retryQueue.indexOf(pageIndex);\n      if (queuePosition === -1 && retryPosition === -1) return;\n      if (answerIndex === page.answer) {\n        progress.lastMiss = null;\n        if (!progress.lessonCorrect.includes(pageIndex)) progress.lessonCorrect.push(pageIndex);\n        if (queuePosition !== -1) queue.splice(queuePosition, 1);\n        if (retryPosition !== -1) retryQueue.splice(retryPosition, 1);\n        progress.lessonPage += 1;\n        if (!queue.length && !retryQueue.length) {\n          finishLesson(module, progress);\n        } else {\n          saveState();\n          renderCourse();\n        }\n      } else {\n        if (queuePosition !== -1) {\n          queue.splice(queuePosition, 1);\n        } else {\n          retryQueue.splice(retryPosition, 1);\n        }\n        retryQueue.push(pageIndex);\n        progress.lessonMisses.push(pageIndex);\n        progress.lastMiss = {\n          questionNumber: Math.max(1, pageIndex),\n          answer: page.options[page.answer],\n          explanation: page.explanation || \"Review the idea, then try the question again when it returns.\"\n        };\n        saveState();\n        renderCourse();\n      }\n    }\n\n    function finishLesson(module, progress) {\n      if (progress.lessonDone || progress.activityResult) return;\n      const lessonInfo = currentLesson(module, progress);\n      const correct = lessonPracticeTotal(module, progress);\n      const total = correct + progress.lessonMisses.length;\n      const accuracy = Math.round((correct / total) * 100);\n      const durationMs = elapsedTime(progress.lessonStartedAt);\n      const reward = performanceReward(module.lessonXp, correct, total, durationMs);\n      progress.completedLessons = Math.max(progress.completedLessons || 0, lessonInfo.index + 1);\n      state.streak += 1;\n      progress.activityResult = {\n        kind: \"lesson\",\n        title: `${lessonInfo.lesson.title} results`,\n        correct,\n        total,\n        accuracy,\n        durationMs,\n        totalXp: reward.totalXp,\n        xpNote: `${formatXpPart(reward.accuracyXp)} accuracy XP + ${formatXpPart(reward.speedXp)} speed XP. ${reward.overtimeSeconds ? `${reward.overtimeSeconds} XP was removed for time after 2 minutes.` : \"Finished within 2 minutes, so no speed XP was removed.\"} Missed questions count as extra attempts.`,\n        nextLabel: lessonInfo.index + 1 < lessonInfo.total ? \"Continue to next lesson\" : \"Continue to module quiz\"\n      };\n      progress.skipEligible = true;\n      addXp(reward.totalXp, `${module.shortTitle} ${lessonInfo.lesson.title}`);\n      saveState();\n      renderAll();\n    }\n\n    function answerCourseQuestion(itemId, answerIndex) {\n      const item = courseItems.find(entry => entry.id === itemId);\n      if (!item || state.completed[item.id]) return;\n      const progress = getProgress(item.id);\n      const questions = item.kind === \"module\" ? item.quizQuestions : item.questions;\n      const indexKey = item.kind === \"module\" ? \"quizIndex\" : \"testIndex\";\n      const correctKey = item.kind === \"module\" ? \"quizCorrect\" : \"testCorrect\";\n      const answeredKey = item.kind === \"module\" ? \"quizAnswered\" : \"testAnswered\";\n      const startedKey = item.kind === \"module\" ? \"quizStartedAt\" : \"testStartedAt\";\n      if (!progress[startedKey]) progress[startedKey] = Date.now();\n      const question = questions[progress[indexKey]];\n      markAnswerButtons(answerIndex, question.answer);\n      progress[answeredKey] += 1;\n      if (answerIndex === question.answer) progress[correctKey] += 1;\n      progress[indexKey] += 1;\n      if (progress[indexKey] >= questions.length) {\n        window.setTimeout(() => finishQuestionSet(item, progress), 500);\n      } else {\n        saveState();\n        window.setTimeout(renderCourse, 500);\n      }\n    }\n\n    function finishQuestionSet(item, progress) {\n      if (item.kind === \"module\") {\n        const total = item.quizQuestions.length;\n        const accuracy = Math.round((progress.quizCorrect / total) * 100);\n        const durationMs = elapsedTime(progress.quizStartedAt);\n        const reward = performanceReward(item.quizXp, progress.quizCorrect, total, durationMs);\n        const perfectXp = progress.quizCorrect === total ? item.perfectXp : 0;\n        progress.quizDone = true;\n        state.streak += 1;\n        addXp(reward.totalXp, `${item.shortTitle} quiz performance`);\n        if (perfectXp) addXp(perfectXp, `${item.shortTitle} perfect quiz`);\n        addXp(item.moduleXp, `${item.shortTitle} module`);\n        state.completed[item.id] = true;\n        progress.activityResult = {\n          kind: \"quiz\",\n          title: `${item.shortTitle} quiz results`,\n          correct: progress.quizCorrect,\n          total,\n          accuracy,\n          durationMs,\n          totalXp: reward.totalXp + perfectXp + item.moduleXp,\n          xpNote: `${formatXpPart(reward.accuracyXp)} accuracy XP + ${formatXpPart(reward.speedXp)} speed XP, plus ${item.moduleXp} module XP${perfectXp ? ` and ${perfectXp} perfect-score XP` : \"\"}. ${reward.overtimeSeconds ? `${reward.overtimeSeconds} XP was removed for time after 2 minutes.` : \"No speed XP was removed.\"}`,\n          nextLabel: \"Continue course\"\n        };\n      } else {\n        const total = item.questions.length;\n        const accuracy = Math.round((progress.testCorrect / total) * 100);\n        const durationMs = elapsedTime(progress.testStartedAt);\n        const reward = performanceReward(item.xp, progress.testCorrect, total, durationMs);\n        const perfectXp = progress.testCorrect === total ? item.perfectXp : 0;\n        progress.testDone = true;\n        state.streak += 1;\n        addXp(reward.totalXp, `${item.title} performance`);\n        if (perfectXp) addXp(perfectXp, `${item.title} perfect score`);\n        state.completed[item.id] = true;\n        progress.activityResult = {\n          kind: \"bigTest\",\n          title: `${item.title} results`,\n          correct: progress.testCorrect,\n          total,\n          accuracy,\n          durationMs,\n          totalXp: reward.totalXp + perfectXp,\n          xpNote: `${formatXpPart(reward.accuracyXp)} accuracy XP + ${formatXpPart(reward.speedXp)} speed XP${perfectXp ? `, plus ${perfectXp} perfect-score XP` : \"\"}. ${reward.overtimeSeconds ? `${reward.overtimeSeconds} XP was removed for time after 2 minutes.` : \"No speed XP was removed.\"}`,\n          nextLabel: \"Continue course\"\n        };\n      }\n      saveState();\n      renderAll();\n    }\n\n    function continueCourseResult(itemId) {\n      const item = courseItems.find(entry => entry.id === itemId);\n      if (!item) return;\n      const progress = getProgress(item.id);\n      const result = progress.activityResult;\n      if (!result) return;\n\n      if (result.kind === \"lesson\") {\n        const lessonInfo = currentLesson(item, progress);\n        progress.activityResult = null;\n        progress.lessonStartedAt = 0;\n        progress.lastMiss = null;\n        if (lessonInfo.index + 1 < lessonInfo.total) {\n          progress.lessonIndex = lessonInfo.index + 1;\n          progress.queueLessonIndex = null;\n          progress.lessonPage = 0;\n          progress.lessonQueue = null;\n          progress.lessonRetryQueue = [];\n          progress.lessonCorrect = [];\n          progress.lessonMisses = [];\n        } else {\n          progress.lessonDone = true;\n          progress.lessonPage = lessonPagesFor(item, progress).length - 1;\n        }\n        courseOverviewMode = false;\n      } else if (result.kind === \"skipFailed\") {\n        progress.activityResult = null;\n        progress.skipIndex = 0;\n        progress.skipCorrect = 0;\n        progress.skipMisses = 0;\n        progress.skipStartedAt = 0;\n        state.activeCourseId = item.id;\n        courseOverviewMode = true;\n      } else if (result.kind === \"moduleSkip\") {\n        progress.activityResult = null;\n        progress.skipStartedAt = 0;\n        state.activeCourseId = getNextCourseId(item.id);\n        courseOverviewMode = false;\n      } else {\n        progress.activityResult = null;\n        state.activeCourseId = getNextCourseId(item.id);\n        courseOverviewMode = false;\n      }\n      saveState();\n      renderAll();\n    }\n\n    function getNextCourseId(itemId) {\n      const index = courseItems.findIndex(item => item.id === itemId);\n      return (courseItems[index + 1] || courseItems[index]).id;\n    }\n\n    function collectCourseBonus() {\n      const finish = courseItems.find(item => item.id === \"finish-course\");\n      if (!finish || state.completed[finish.id]) return;\n      state.completed[finish.id] = true;\n      state.streak += 1;\n      addXp(finish.xp, finish.title);\n      saveState();\n      renderAll();\n    }\n\n    function markAnswerButtons(answerIndex, correctIndex) {\n      const panel = document.getElementById(\"lessonPanel\");\n      panel.querySelectorAll(\"[data-answer]\").forEach(button => {\n        const isCorrect = Number(button.dataset.answer) === correctIndex;\n        button.classList.toggle(\"correct\", isCorrect);\n        button.classList.toggle(\"wrong\", Number(button.dataset.answer) === answerIndex && !isCorrect);\n        button.disabled = true;\n      });\n      panel.querySelectorAll(\"[data-lesson-answer]\").forEach(button => {\n        const isCorrect = Number(button.dataset.lessonAnswer) === correctIndex;\n        button.classList.toggle(\"correct\", isCorrect);\n        button.classList.toggle(\"wrong\", Number(button.dataset.lessonAnswer) === answerIndex && !isCorrect);\n        button.disabled = true;\n      });\n    }\n\n    function taskDaysAway(day) {\n      if (!day) return 0;\n      const then = new Date(day);\n      if (!Number.isFinite(then.getTime())) return 0;\n      const now = new Date();\n      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();\n      const thenStart = new Date(then.getFullYear(), then.getMonth(), then.getDate()).getTime();\n      return Math.max(0, Math.floor((todayStart - thenStart) / 86400000));\n    }\n\n    function nextTaskStreak(daysAway) {\n      const savedStreak = Math.max(0, Number(state.taskStreak) || 0);\n      if (daysAway === 1) return savedStreak + 1;\n      if (daysAway > 1) return 1;\n      return Math.max(savedStreak, 1);\n    }\n\n    function currentTaskProfile(daysAway = taskDaysAway(state.taskLastSeenDay || state.taskDay || state.claimed.daily), taskStreak = nextTaskStreak(daysAway)) {\n      if (daysAway >= 7) return taskProfiles.returning;\n      if (taskStreak >= 28) return taskProfiles.mastery;\n      if (taskStreak >= 14) return taskProfiles.advanced;\n      if (taskStreak >= 7) return taskProfiles.building;\n      return taskProfiles.starter;\n    }\n\n    function taskProfileFromState() {\n      return Object.values(taskProfiles).find(profile => profile.id === state.taskProfile) || currentTaskProfile();\n    }\n\n    function shuffleTasks(items) {\n      const copy = [...items];\n      for (let index = copy.length - 1; index > 0; index -= 1) {\n        const swap = Math.floor(Math.random() * (index + 1));\n        [copy[index], copy[swap]] = [copy[swap], copy[index]];\n      }\n      return copy;\n    }\n\n    function taskTemplateFor(level, rank) {\n      const exactRank = taskBank[level].filter(task => task.rank === rank);\n      const fallback = taskBank[level].filter(task => task.rank <= rank);\n      return shuffleTasks(exactRank.length ? exactRank : fallback)[0];\n    }\n\n    function generateTasks() {\n      const today = new Date().toDateString();\n      const daysAway = taskDaysAway(state.taskLastSeenDay || state.taskDay || state.claimed.daily);\n      const taskStreak = nextTaskStreak(daysAway);\n      const profile = currentTaskProfile(daysAway, taskStreak);\n      state.tasks = Object.keys(taskXp).map(level => {\n        const template = taskTemplateFor(level, profile.rank);\n        const start = taskMetricValue(template.metric);\n        return {\n          id: `${template.id}-${level}-${today}`,\n          level,\n          text: template.text,\n          metric: template.metric,\n          target: start + template.amount,\n          xp: taskXp[level],\n          done: false,\n          proof: \"\"\n        };\n      });\n      state.taskDay = today;\n      state.taskLastSeenDay = today;\n      state.taskStreak = taskStreak;\n      state.taskProfile = profile.id;\n      state.taskVersion = TASK_VERSION;\n      saveState();\n    }\n\n    function renderTasks() {\n      ensureDailyTasks();\n      const grid = document.getElementById(\"taskGrid\");\n      const profile = taskProfileFromState();\n      const completed = state.tasks.filter(task => task.done).length;\n      const streakLabel = `${state.taskStreak || 1}-day daily task streak`;\n      document.getElementById(\"taskGuide\").textContent = `${profile.guide} ${streakLabel}. ${completed}/3 complete today.`;\n      grid.innerHTML = state.tasks.map(task => `\n        <article class=\"card task ${task.level.toLowerCase()}\">\n          <div>\n            <span class=\"difficulty\">${task.level} Task</span>\n            <h3 style=\"margin-top:12px\">${task.text}</h3>\n          </div>\n          ${task.done\n            ? `<div class=\"task-done\">Completed today</div>`\n            : taskActivityType(task)\n              ? `<div class=\"task-complete\">\n                  <p class=\"muted\">Complete the related activity in the app, then check your progress here.</p>\n                  <button class=\"btn green\" data-task=\"${task.id}\">Check progress +${task.xp} XP</button>\n                </div>`\n              : `<div class=\"task-complete\">\n                  <textarea class=\"task-work\" data-task-proof=\"${task.id}\" placeholder=\"Show your work here...\" aria-label=\"Work for ${task.level} task\"></textarea>\n                  <button class=\"btn green\" data-task=\"${task.id}\">Submit work +${task.xp} XP</button>\n                </div>`}\n        </article>\n      `).join(\"\");\n      grid.querySelectorAll(\"[data-task]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          const task = state.tasks.find(item => item.id === button.dataset.task);\n          if (!task) return;\n          const proofInput = [...grid.querySelectorAll(\"[data-task-proof]\")].find(input => input.dataset.taskProof === task.id);\n          const proof = proofInput ? proofInput.value.trim() : \"\";\n          const check = taskProofIsValid(task, proof);\n          if (!check.valid) {\n            showToast(check.reason);\n            proofInput?.focus();\n            return;\n          }\n          task.done = true;\n          task.proof = proof;\n          task.completedAt = Date.now();\n          addXp(task.xp, `${task.level} task`);\n          saveState();\n          renderTasks();\n        });\n      });\n    }\n\n    function taskActivityType(task) {\n      return task.metric || \"\";\n    }\n\n    function ensureDailyTasks() {\n      const today = new Date().toDateString();\n      const valid = state.taskVersion === TASK_VERSION && Array.isArray(state.tasks) && state.tasks.length === 3 && state.tasks.every(task => task.metric && Number.isFinite(Number(task.target)) && task.level && typeof task.done === \"boolean\");\n      if (state.taskDay !== today || !valid) {\n        generateTasks();\n        return;\n      }\n      let changed = false;\n      state.tasks = state.tasks.map(task => {\n        if (!task.done || taskActivityType(task) || taskProofIsValid(task, String(task.proof || \"\")).valid) return task;\n        changed = true;\n        return { ...task, done: false, proof: \"\", completedAt: null };\n      });\n      if (state.taskLastSeenDay !== today) {\n        state.taskLastSeenDay = today;\n        changed = true;\n      }\n      if (changed) saveState();\n    }\n\n    function taskCheck(valid, reason) {\n      return { valid, reason };\n    }\n\n    function taskHasTwoNotes(proof) {\n      const notes = proof.split(/\\n+|[.!?;]+/).map(note => note.trim()).filter(Boolean);\n      if (notes.length >= 2 && new Set(notes.map(note => note.toLowerCase())).size >= 2) return true;\n      return /both|but|while|whereas|compared|unlike|more|less|difference/i.test(proof);\n    }\n\n    function taskMarketMentionCount(proof, category, status = \"\") {\n      const lowerProof = proof.toLowerCase();\n      const group = markets.find(item => item.category === category);\n      if (!group) return 0;\n      return group.items.filter(([name, itemStatus, note, symbol]) => {\n        if (status && itemStatus !== status) return false;\n        return lowerProof.includes(String(name).toLowerCase()) || (symbol && lowerProof.includes(String(symbol).toLowerCase()));\n      }).length;\n    }\n\n    function taskCryptoMentionCount(proof) {\n      const lowerProof = proof.toLowerCase();\n      return [\"bitcoin\", \"ethereum\", \"dogecoin\"].filter(name => lowerProof.includes(name)).length;\n    }\n\n    function taskCompletedLessons() {\n      return courseItems.filter(item => item.kind === \"module\").reduce((total, item) => {\n        const progress = getProgress(item.id);\n        return total + (progress.skipped ? 0 : (progress.completedLessons || 0));\n      }, 0);\n    }\n\n    function taskCompletedQuizzes() {\n      return courseItems.filter(item => {\n        const progress = getProgress(item.id);\n        return item.kind === \"module\" && progress.quizDone && !progress.skipped;\n      }).length;\n    }\n\n    function taskPerfectQuizzes() {\n      return courseItems.filter(item => item.kind === \"module\").filter(item => {\n        const progress = getProgress(item.id);\n        return !progress.skipped && progress.quizDone && progress.quizCorrect === item.quizQuestions.length;\n      }).length;\n    }\n\n    function taskCompletedFinalTests() {\n      return courseItems.filter(item => item.kind === \"bigTest\" && getProgress(item.id).testDone).length;\n    }\n\n    function taskMetricValue(metric) {\n      if (metric === \"lessons\") return taskCompletedLessons();\n      if (metric === \"quizzes\") return taskCompletedQuizzes();\n      if (metric === \"perfectQuizzes\") return taskPerfectQuizzes();\n      if (metric === \"finalTests\") return taskCompletedFinalTests();\n      return 0;\n    }\n\n    function taskHeldCategories() {\n      const positiveSymbols = new Set(Object.entries(state.portfolio.holdings || {}).filter(([, holding]) => Number(holding.units) > 0).map(([symbol]) => symbol));\n      return new Set(markets.filter(group => group.items.some(([, , , symbol]) => positiveSymbols.has(symbol))).map(group => group.category));\n    }\n\n    function taskHoldingCount() {\n      return Object.values(state.portfolio.holdings || {}).filter(holding => Number(holding.units) > 0).length;\n    }\n\n    function taskProofIsValid(task, proof) {\n      if (task.metric) {\n        return taskCheck(taskMetricValue(task.metric) >= Number(task.target), \"Finish the listed learning activity after today's task board opened, then check progress again.\");\n      }\n      const rule = task.rule;\n      if (rule === \"paper-trade\") return taskCheck(Boolean(state.claimed.trade), \"Make a paper trade first, then check progress again.\");\n      if (rule === \"lesson-one\") return taskCheck(taskCompletedLessons() >= 1, \"Finish one lesson first, then check progress again.\");\n      if (rule === \"lesson-two\") return taskCheck(taskCompletedLessons() >= 2, \"Finish two lessons first, then check progress again.\");\n      if (rule === \"quiz-one\") return taskCheck(taskCompletedQuizzes() >= 1, \"Finish one quiz first, then check progress again.\");\n      if (rule === \"quiz-two\") return taskCheck(taskCompletedQuizzes() >= 2, \"Finish two quizzes first, then check progress again.\");\n      if (rule === \"perfect-quiz-one\") return taskCheck(taskPerfectQuizzes() >= 1, \"Finish a quiz with every answer correct first.\");\n      if (rule === \"perfect-quiz-two\") return taskCheck(taskPerfectQuizzes() >= 2, \"Finish two perfect quizzes first, then check progress again.\");\n      if (rule === \"final-test-one\") return taskCheck(taskCompletedFinalTests() >= 1, \"Finish one final test first, then check progress again.\");\n      if (rule === \"final-test-two\") return taskCheck(taskCompletedFinalTests() >= 2, \"Finish two final tests first, then check progress again.\");\n      if (rule === \"holdings-two\") return taskCheck(taskHoldingCount() >= 2, \"Build paper positions in two markets first, then check progress again.\");\n      if (rule === \"holdings-four\") return taskCheck(taskHoldingCount() >= 4, \"Build paper positions in four markets first, then check progress again.\");\n      if (rule === \"portfolio-balanced\") {\n        const categories = taskHeldCategories();\n        return taskCheck(categories.has(\"Crypto\") && categories.has(\"National\") && categories.has(\"International\"), \"Build positive paper positions in crypto, national, and international markets first.\");\n      }\n      if (rule === \"crypto-coin\") return taskCheck(taskCryptoMentionCount(proof) >= 1, \"Please check the crypto list and enter one coin from it.\");\n      if (rule === \"green-market\") {\n        const lowerProof = proof.toLowerCase();\n        const hasMarket = markets.some(group => group.items.some(([name, status, note, symbol]) => {\n          if (status !== \"can\") return false;\n          return lowerProof.includes(String(name).toLowerCase()) || (symbol && lowerProof.includes(String(symbol).toLowerCase()));\n        }));\n        return taskCheck(hasMarket && /because|means|is|market|stock|crypto|company|index|etf/i.test(proof), \"Please check the market list and explain what your selected market is.\");\n      }\n      if (rule === \"color-key\") return taskCheck(/bitcoin/i.test(proof) && /qqq/i.test(proof) && /openai/i.test(proof) && /can buy|buy|holding|hold|choose|cant|can't/i.test(proof), \"Please check the color key and include all three listed items with their categories.\");\n      if (rule === \"market-pair\") return taskCheck(taskMarketMentionCount(proof, \"International\", \"can\") >= 1 && taskMarketMentionCount(proof, \"National\", \"can\") >= 1, \"Please check the national and international lists and include one can-buy item from each.\");\n      if (rule === \"etf-note\") return taskCheck(/qqq|gold/i.test(proof) && /etf|fund|basket|track/i.test(proof), \"Please check the market list and name a can-buy ETF with a short description.\");\n      if (rule === \"watchlist\") return taskCheck(taskMarketMentionCount(proof, \"National\", \"can\") + taskMarketMentionCount(proof, \"International\", \"can\") >= 3 && /etf|watchlist/i.test(proof), \"Please check the market list and include three can-buy markets, including an ETF.\");\n      if (rule === \"tesla-toyota\") return taskCheck(/tesla/i.test(proof) && /toyota/i.test(proof) && taskHasTwoNotes(proof) && /risk|difference|compare|similar|company|stock|ev|hybrid|both|while|whereas|more|less|unlike/i.test(proof), \"Please check the task wording and write one note for each company plus a comparison or risk detail.\");\n      if (rule === \"crypto-compare\") return taskCheck(taskCryptoMentionCount(proof) >= 2 && taskHasTwoNotes(proof) && /risk|difference|compare|similar|both|while|whereas|more|less|unlike/i.test(proof), \"Please check the crypto list and compare two coins in separate notes.\");\n      if (rule === \"penny-risk\") return taskCheck(taskMarketMentionCount(proof, \"Penny markets\", \"can\") >= 2 && /risk|liquid|hype|volatil|loss|spread/i.test(proof) && taskHasTwoNotes(proof), \"Please check the penny-market list and add a separate risk note for each selected market.\");\n      if (rule === \"holding-economy\") return taskCheck(/vix/i.test(proof) && /private|openai|anthropic|perplexity|skild|discord/i.test(proof) && /holding|hold|cant|can't|not public|watch/i.test(proof), \"Please check the market key and explain why these are holding-economy items.\");\n      return taskCheck(Boolean(proof.trim()), \"Add an answer before submitting.\");\n    }\n\n    function wireDashboard() {\n      document.querySelectorAll(\"[data-tab]\").forEach(tab => {\n        tab.addEventListener(\"click\", () => {\n          document.querySelectorAll(\"[data-tab]\").forEach(item => item.classList.toggle(\"active\", item === tab));\n          document.querySelectorAll(\"[data-panel]\").forEach(panel => panel.classList.toggle(\"hidden\", panel.dataset.panel !== tab.dataset.tab));\n          if (tab.dataset.tab === \"learn\") {\n            renderCourse();\n          } else {\n            document.getElementById(\"dashboard\").classList.remove(\"lesson-focus\");\n            if (tab.dataset.tab === \"settings\") renderSettings();\n          }\n        });\n      });\n      document.getElementById(\"dailyBtn\").addEventListener(\"click\", () => {\n        const today = new Date().toDateString();\n        if (state.claimed.daily === today) {\n          showToast(\"Daily login already claimed today.\");\n          return;\n        }\n        state.claimed.daily = today;\n        state.streak += 1;\n        addXp(10, \"daily login\");\n        saveState();\n        renderAll();\n      });\n      document.getElementById(\"freezeBtn\").addEventListener(\"click\", () => {\n        if (state.xp < 250) {\n          showToast(\"You need 250 XP for a Streak Freeze.\");\n          return;\n        }\n        addXp(-250, \"Streak Freeze\");\n      });\n      document.getElementById(\"settingsForm\").addEventListener(\"submit\", event => {\n        event.preventDefault();\n        const first = document.getElementById(\"settingsFirst\").value.trim();\n        const last = document.getElementById(\"settingsLast\").value.trim();\n        const age = Number(document.getElementById(\"settingsAge\").value);\n        const level = document.getElementById(\"settingsLevel\").value;\n        if (!first || !last || !Number.isInteger(age) || age < 1 || age > 120) {\n          showToast(\"Enter a first name, last name, and age from 1 to 120.\");\n          return;\n        }\n        state.profile.first = first;\n        state.profile.last = last;\n        state.profile.age = String(age);\n        state.profile.level = level;\n        saveState();\n        renderStats();\n        renderSettings();\n        showToast(\"Profile updated.\");\n      });\n      document.getElementById(\"resetAccountBtn\").addEventListener(\"click\", () => {\n        const confirmed = window.confirm(\"Reset your account? This deletes your profile, XP, streak, course progress, and completed tasks.\");\n        if (!confirmed) return;\n        localStorage.removeItem(\"investQuestState\");\n        localStorage.removeItem(MARKET_CHART_CACHE_KEY);\n        location.reload();\n      });\n    }\n\n    function renderAll() {\n      renderStats();\n      renderMarkets();\n      renderCourse();\n      renderTasks();\n      renderSettings();\n    }\n\n    wireOnboarding();\n    wireDashboard();\n    renderOnboarding();\n  </script>\n</body>\n</html>\n";

function jsonResponse(body, status = 200) {
  return new Response(body, {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store"
    }
  });
}

async function proxyYahooChart(url) {
  const symbol = (url.searchParams.get("symbol") || "").trim();
  const range = url.searchParams.get("range") || "1d";
  const interval = url.searchParams.get("interval") || "1m";
  const includePrePost = url.searchParams.get("includePrePost") || "true";

  if (!symbol) {
    return jsonResponse(JSON.stringify({ error: "Missing symbol" }), 400);
  }

  const yahooUrl = new URL(
    "https://query1.finance.yahoo.com/v8/finance/chart/" + encodeURIComponent(symbol)
  );
  yahooUrl.searchParams.set("range", range);
  yahooUrl.searchParams.set("interval", interval);
  yahooUrl.searchParams.set("includePrePost", includePrePost);
  yahooUrl.searchParams.set("_", String(Date.now()));

  try {
    const response = await fetch(yahooUrl, {
      headers: {
        "User-Agent": "Mozilla/5.0 InvestQuest/1.0",
        "Accept": "application/json"
      }
    });
    return jsonResponse(await response.text(), response.status);
  } catch {
    return jsonResponse(JSON.stringify({ error: "Yahoo chart request failed" }), 504);
  }
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/api/chart") {
      return proxyYahooChart(url);
    }

    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(INDEX_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "no-cache"
        }
      });
    }

    return new Response("Not found", { status: 404 });
  }
};
